(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c38"]=[{"id":"00014924","register_sub_id":"101","register_pk":"519184","name":"宇倍神社本殿","kana":"うべじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市国府町宮ノ下651","lat":35.48093056,"lng":134.26875833,"geo_status":"db","era":"明治31年／明治41年改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0283","desc":"稲葉山南西麓に位置する因幡国一宮の本殿。東面する切妻造平入檜皮葺で正面1間背面3間、側面２間、向拝1間付。組物は舟肘木、妻飾は豕扠首、軒は二軒繁垂木。四周に縁と高欄が廻り、向拝に浜縁を付す。全体に装飾抑えつつも扉に菊紋を付して荘厳した本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014924"},{"id":"00002812","register_sub_id":"101","register_pk":"103802","name":"大神山神社石の大鳥居","kana":"おおがみやまじんじゃいしのおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県西伯郡大山町大山","lat":35.38987297,"lng":133.536041,"geo_status":"db","era":"嘉永7","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"石造、高さ8.5m、幅12m","structure_material":"石造","registered":"2002.06.25(平成14.06.25)","register_no":"31 － 0055","desc":"高さ８．５ｍ，柱の直径約２尺の石造明神鳥居である。柱には建立時の願主や，施主及び修理世話人などの名が刻まれている。山陽方面から大山寺への参道入口にあたる大山横手道にあり，規模も雄大で，「石の大鳥居」として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002812"},{"id":"00014930","register_sub_id":"101","register_pk":"519190","name":"加知彌神社随神門","kana":"かちみじんじゃずいしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市鹿野町寺内155-1","lat":35.47848611,"lng":134.05256667,"geo_status":"db","era":"文政13年(1830)／昭和中期改修","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造、銅板葺、建築面積15㎡","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0289","desc":"境内入口に東面して建つ桁行三間梁間二間切妻造平入銅板葺の随神門。棟通りを東に寄せた変則的な八脚門形式の平面で、中央間は土間で化粧屋根裏、両脇間の西間は床と天井を張り随神を安置、東間は吹放ちの土間で天井を張り随神の礼拝場とした特徴的なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014930"},{"id":"00014929","register_sub_id":"101","register_pk":"519189","name":"加知彌神社拝殿","kana":"かちみじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市鹿野町寺内155-1","lat":35.47849722,"lng":134.05209167,"geo_status":"db","era":"大正10年／昭和中期改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0288","desc":"本殿東に東面する桁行三間梁間三間、入母屋造銅板葺の拝殿。四周に縁と高欄を巡らし、正面に柱間の広い唐破風造の向拝を付す。内部は一室の拭板敷で格天井を張る。全体に装飾少なく簡素なつくりとし、大振りな唐破風の向拝など、本殿の形式と呼応する拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014929"},{"id":"00014928","register_sub_id":"101","register_pk":"519188","name":"加知彌神社本殿","kana":"かちみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市鹿野町寺内155-1","lat":35.47850278,"lng":134.05186667,"geo_status":"db","era":"文政13年(1830)／昭和38年改修","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0287","desc":"鹿野城跡北方に位置する式内社の本殿。境内中央に東面する桁行三間梁間三間、切妻造妻入銅板葺。内外陣の前方一間を吹放ち、さらに正面に広い柱間で唐破風造の一間向拝を付す。向拝廻りの彫刻以外は全体に装飾を抑えつつも、大規模で独特な存在感を示す本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014928"},{"id":"00013177","register_sub_id":"101","register_pk":"368306","name":"賀茂神社本殿","kana":"かもじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県倉吉市葵町584","lat":35.42909167,"lng":133.82903889,"geo_status":"db","era":"江戸末期／平成15年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"31 － 0269","desc":"倉吉市街地南方の丘陵上に西面して建つ産土社。正面一間、背面二間、側面二間、入母屋造妻入、銅板葺で、四方に高欄付の縁を廻し、向拝一間を設ける。虹梁上部の龍、木鼻の獏、獅子、正面嵌板の獅子、牡丹など、各所を精緻な彫刻で華やかに飾る優美な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013177"},{"id":"00012627","register_sub_id":"101","register_pk":"367921","name":"蚊屋島神社神楽殿","kana":"かやしまじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治33年／昭和51年増築","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0261","desc":"拝殿前方にあり、参道に東面して建つ。東側四間半の入母屋造の舞台と控間が当初、西側二間の切妻造の入口兼倉庫が後補である。舞台は12畳半敷で参道側と本殿側の二面に高欄付の縁を廻し、格天井を張る。随神門や宝庫と同じく近代的な表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012627"},{"id":"00012626","register_sub_id":"101","register_pk":"367920","name":"蚊屋島神社神饌所及び渡廊","kana":"かやしまじんじゃしんせんしょおよびわたろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治33年／昭和51年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0260","desc":"拝殿東面と渡廊で接続し、南面して建つ。桁行三間梁間二間、切妻造妻入、内部は前方が土間、後方が畳敷で床を高く張り、西面に戸口を設ける。渡廊は桁行四間梁間一間で、全体に優美な弧を描く。機能的な整備が図られた神社の近代化の一端を示す社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012626"},{"id":"00012631","register_sub_id":"101","register_pk":"367925","name":"蚊屋島神社随神門","kana":"かやしまじんじゃずいしんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治33年／昭和51年・平成17年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0265","desc":"境内正面の参道上に南面して建つ、三間一戸の八脚門。切妻造で、妻飾は虹梁大瓶束、破風に蕪懸魚を吊る。幅広の中央間は開放とし、両脇間は門口側を格子、三方を板壁として随神像を安置する。奥行狭く間口の広い外観で、境内正面の景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012631"},{"id":"00012630","register_sub_id":"101","register_pk":"367924","name":"蚊屋島神社天神社","kana":"かやしまじんじゃてんじんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治元年頃／昭和51年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.4㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0264","desc":"境内後方にあり、本殿東側に南面して建つ。三間社流見世棚造で、虹梁大瓶束の妻飾や若葉の透彫木鼻をもつ向拝の虹梁型頭貫など細部装飾を含め、規模･形式とも豊受社と寸分違わない。豊受社と対置され、伝統的な境内空間を構成する、端正な意匠の境内社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012630"},{"id":"00012629","register_sub_id":"101","register_pk":"367923","name":"蚊屋島神社豊受社","kana":"かやしまじんじゃとようけしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治元年頃／昭和51年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.4㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0263","desc":"境内後方にあり、本殿西側に南面して建つ。三間社流見世棚造で、前後とも一軒疎垂木、妻飾は虹梁大瓶束、破風拝みに蕪懸魚を飾る。身舎と向拝は海老虹梁でつなぎ、向拝両端の柱を虹梁型頭貫で結ぶ。伝統的な境内空間を構成する、端正な意匠の境内社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012629"},{"id":"00012625","register_sub_id":"101","register_pk":"367919","name":"蚊屋島神社幣殿及び拝殿","kana":"かやしまじんじゃへいでんおよびはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"天保4年（1833）／明治元年・同33年改修","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0259","desc":"本殿正面に接続し、南面して建つ。拝殿は桁行五間梁間二間の入母屋造で、正面に入母屋造軒唐破風付の向拝、背面に両下造の幣殿を出す。内部は畳敷、格天井で、幣殿の床を一段上げ、本殿前に木階五級を設ける。装飾豊かな正面で、社頭景観を華やかに整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012625"},{"id":"00012628","register_sub_id":"101","register_pk":"367922","name":"蚊屋島神社宝庫（仮殿）","kana":"かやしまじんじゃほうこ（かりでん）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治33年／昭和51年・平成17年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0262","desc":"拝殿前方にあり、参道に西面して建つ。桁行三間梁間二間、切妻造妻入で、側背面を板壁とし、正面に切妻造の吹放し向拝を付す。軒は一軒疎垂木。内部は10畳敷で後方に祭壇を設ける。装飾の少ない外観で随神門や神楽殿と同じく近代的な表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012628"},{"id":"00012624","register_sub_id":"101","register_pk":"367918","name":"蚊屋島神社本殿","kana":"かやしまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治元年／平成17年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0258","desc":"箕蚊屋平野中央部に鎮座する、蚊屋庄29ヵ村の産土社。本殿は正面三間側面三間の切妻造妻入で、正面側柱を角柱とする。内部は外陣、内陣、内々陣に分け、外陣の床と天井を一段下げ、正面中央間を幣殿に開放する。外観を大社造風にする独特な形式の大型本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012624"},{"id":"00009826","register_sub_id":"101","register_pk":"195655","name":"興禅寺本堂","kana":"こうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市栗谷町10","lat":35.50444504,"lng":134.24126461,"geo_status":"db","era":"文化11／明治期・大正期増築","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積214㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"31 － 0183","desc":"入母屋造平入の主体部の前面に入母屋造妻入の向拝を建て、間を両下造の御拝ノ間で繋ぐという複雑な屋根形態をもち、赤色瓦を葺く。主体部は手前より次ノ間、高間、霊壇とし、最奥の霊壇は折上格天井に花鳥などを彩画する華やかな意匠で、藩主霊屋の由緒を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009826"},{"id":"00012010","register_sub_id":"101","register_pk":"210951","name":"山王日吉神社本殿","kana":"さんのうひえじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市布勢字村土居1","lat":35.50435,"lng":134.176273,"geo_status":"db","era":"嘉永3年（1850）／昭和55年改修","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"31-229","desc":"正面一間、側背面二間流造、銅板葺、四周に切目縁を廻らす。棟札から嘉永三年の建築、棟梁木原傳兵衛であることが判る。向拝の蟇股に池田家家紋、正面の引違戸には池田家家紋と徳川家家紋が並ぶ。「布勢の山王さん」として地域に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012010"},{"id":"00007112","register_sub_id":"101","register_pk":"108094","name":"常忍寺本堂","kana":"じょうにんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市行徳3-977","lat":35.50243969,"lng":134.22166286,"geo_status":"db","era":"文政元／天保9改修・平成10移築","year":1818,"year_source":"db","year_min":1818,"year_max":1818,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"31 － 0113","desc":"南面する５間堂で、入母屋造瓦葺に１間向拝を付ける。正面の柱は円柱で、柱上粽付で三斗を組む。内部は正面１間通りを外陣とし、その奥４間を内陣、両脇を余間とし、内陣中央後寄りに須弥壇を構える。典型的な日蓮宗本堂形式になり、細部様式に時代を反映する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007112"},{"id":"00014932","register_sub_id":"101","register_pk":"519192","name":"杉谷神社拝殿及び幣殿","kana":"すぎたにじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市気高町日光1035","lat":35.51332778,"lng":134.069575,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0291","desc":"境内中央に西面して建つ拝殿及び幣殿。拝殿は入母屋造妻入桟瓦葺の東西棟で、正面に一間の向拝を設け、切目縁を付す。内部は一室の畳敷とし、竿縁天井を高く張る。本殿に向かう背面上段に切妻造桟瓦葺の弊殿を張出す。本殿と一体的に境内景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014932"},{"id":"00014931","register_sub_id":"101","register_pk":"519191","name":"杉谷神社本殿","kana":"すぎたにじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市気高町日光1035","lat":35.51332778,"lng":134.06966944,"geo_status":"db","era":"大正4年／昭和25年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.3㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0290","desc":"干拓地の旧日光池の東方、丘上にある神社本殿。西面する一間社流造銅板葺、四周に高欄付縁を廻し正面の木階下に浜縁を付す。組物は皿斗付大斗で三斗を組み、妻飾は虹梁大瓶束。全体に装飾少なく簡素にまとめる。設計書も備え近代の社殿造営の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014931"},{"id":"00015084","register_sub_id":"101","register_pk":"529362","name":"大樹寺開山堂","kana":"だいじゅじかいざんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"鳥取県","address":"鳥取県八頭郡八頭町福地408","lat":35.41240278,"lng":134.329425,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"31 - 0293","desc":"本堂背面と渡廊で接続する開山堂。一段高い石積上に西面して建つ入母屋造平入桟瓦葺。内部は一室で格天井を張り、東側に円柱を立て虹梁を渡し須弥壇を設ける。周囲の位牌棚は柱を省略し垂壁を廻らした軽快なつくり。本堂の背後に建ち伽藍の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015084"},{"id":"00015086","register_sub_id":"101","register_pk":"529364","name":"大樹寺鐘楼","kana":"だいじゅじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県八頭郡八頭町福地408","lat":35.41209722,"lng":134.32913889,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.9㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"31 - 0295","desc":"本堂南西に位置する鐘楼。基壇上に東面して建つ入母屋造銅板葺。礎盤上に円柱を内転びに立て正面に中央上方が湾曲する腰貫を用いる。円柱に三斗を組み、軒は二軒繁垂木、中備は蟇股。内部は格天井張。戦時供出した梵鐘再鋳記念の鐘楼で伽藍景観の一翼を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015086"},{"id":"00015085","register_sub_id":"101","register_pk":"529363","name":"大樹寺僧堂","kana":"だいじゅじそうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"鳥取県","address":"鳥取県八頭郡八頭町福地408","lat":35.41250278,"lng":134.32936389,"geo_status":"db","era":"昭和30年／平成23年改修","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"31 - 0294","desc":"本堂の北東に位置する僧堂。西面して建つ入母屋造平入桟瓦葺。内部は一室の土間で竿縁天井を張り、入側に土間の廊下を廻らす。中央には文殊菩薩像を配し、修行用の単を東西に三列設える。往時は中国地方唯一の専門僧堂であったという由緒を伝える大型の僧堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015085"},{"id":"00015083","register_sub_id":"101","register_pk":"529361","name":"大樹寺本堂","kana":"だいじゅじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県八頭郡八頭町福地408","lat":35.41229167,"lng":134.32927778,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積256㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"31 - 0292","desc":"市場城跡東方の山腹にある曹洞宗寺院本堂。境内中央に西面する入母屋造平入桟瓦葺。正面向拝は垂木を湾曲させ、中備、手挟は彫刻豊か。内部は前面を外陣、中央を大間、後方を内陣とし、大間は折上格天井。棟が高い大規模本堂の姿が地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015083"},{"id":"00012020","register_sub_id":"101","register_pk":"210961","name":"大山寺鐘楼","kana":"だいせんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県西伯郡大山町大山字中門院谷9","lat":35.390816,"lng":133.534796,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造、銅板葺、面積11㎡","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"31-239","desc":"本堂西側に北面して並び建つ。桁行一間梁間一間、一重切妻造銅板葺。基壇上に柱を内転びに立て、腰貫、飛貫、頭貫で固める。柱上部に大斗を載せ、十字に組んだ絵様肘木で桁、虹梁を受ける。本堂同様に中世の様式を基調としながら近代的な特徴を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012020"},{"id":"00012019","register_sub_id":"101","register_pk":"210960","name":"大山寺本堂","kana":"だいせんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県西伯郡大山町大山字中門院谷9","lat":35.390999,"lng":133.534841,"geo_status":"db","era":"昭和26年／昭和60年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積251㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"31-238","desc":"木造、正面五間側面六間、宝形造銅板葺、向拝三間正面唐破風付。内部は外陣、内陣、脇陣、後陣からなり、後陣の前より須弥壇を構え内々陣とする。中世寺院の構成を継承しつつ、意匠性豊かな彫刻を用いるなど近代的な要素が加わり、近代寺院建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012019"},{"id":"00010338","register_sub_id":"101","register_pk":"199111","name":"立川稲荷神社中門","kana":"たちかわいなりじんじゃちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市立川町4-218-2","lat":35.492832,"lng":134.247986,"geo_status":"db","era":"大正10年／昭和8年・平成25年改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造、金属板葺、間口2.4m","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"31-0194","desc":"本殿と幣殿の間の石段上に建つ。方一間、切妻造妻入りで、屋根に緩く起りをつける。礎盤上に立つ円柱上に舟肘木を組んで落とし込み、桁を受ける。妻飾は豕扠首とし、正面柱間に上半を竪格子とした桟唐戸を吊る。近代に各地で建てられた神社中門の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010338"},{"id":"00010337","register_sub_id":"101","register_pk":"199110","name":"立川稲荷神社拝殿及び幣殿","kana":"たちかわいなりじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市立川町4-68","lat":35.492779,"lng":134.247905,"geo_status":"db","era":"寛保元年（1741）／大正7年改修","year":1741,"year_source":"db","year_min":1741,"year_max":1741,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"31-0193","desc":"間口三間奥行三間、入母屋造妻入り、桟瓦葺として縁を廻らし、背面に幣殿を張出す。内部は一室で幣殿を上段とし、格天井を張る。妻飾を木連格子とし、正面に構える唐破風造の向拝に、蟇股を二個重ねて彫刻木鼻を付すなど、正面構えの装飾密度を高めた拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010337"},{"id":"00010336","register_sub_id":"101","register_pk":"199109","name":"立川稲荷神社本殿","kana":"たちかわいなりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市立川町4-218-2","lat":35.492883,"lng":134.248054,"geo_status":"db","era":"大正10年／昭和8年・平成25年改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"31-0192","desc":"正面一間背面二間、切妻造金属板葺で四周に縁高欄を廻らし、正面の向拝に浜床を設ける。柱上に舟肘木を落とし込み、軒は二軒繁垂木、妻飾は豕扠首とする。正面と両側面前間に桟唐戸を開き、他は板壁とする。建ちが高く、装飾を抑えた簡明な意匠になる本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010336"},{"id":"00008327","register_sub_id":"101","register_pk":"133969","name":"転法輪寺本堂","kana":"てんぽうりんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県東伯郡琴浦町大字別宮字中屋敷472他","lat":35.42534307,"lng":133.65869337,"geo_status":"db","era":"延享3年(1746)／文政5年(1822)・明治4年・昭和29年改修","year":1746,"year_source":"db","year_min":1746,"year_max":1746,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"31 － 0163","desc":"山麓に占める境内後方に位置する。桁行五間梁間三間の入母屋造妻入桟瓦葺で、軒支柱を建てる。前二間を外陣、奥を内陣とする。内陣は三方に縁をまわし、床を高く張り、背面に接して壇を構え、中央に本尊、脇に脇士等を安置する。村落に所在する近世仏堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008327"},{"id":"00012618","register_sub_id":"101","register_pk":"367912","name":"長田神社祈祷殿","kana":"ながたじんじゃきとうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目103","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"昭和34年／平成19年改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0252","desc":"神門前方に社務所と並び、西面して建つ。桁行7･9メートル梁間4･9メートル、切妻造銅板葺妻入で、正面に唐破風状の向拝を設け、背面に神棚を突出する。内部は畳敷で、奥5畳の床を一段高くして内陣とする。門前景観における近代化の様相を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012618"},{"id":"00012616","register_sub_id":"101","register_pk":"367910","name":"長田神社神饌所（仮殿）","kana":"ながたじんじゃしんせんじょ（かりでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目101","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"大正4年／大正13年移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0250","desc":"本殿北側に南面して建つ。桁行二間半梁間一間半の入母屋造鉄板葺で、正面東寄りに玄関、東側面に納屋を下屋で設ける。内部は玄関に面して三畳間を設け、北面全面を押入とする。西半は土間とし、西側面に勝手口を開く。近代的な境内の構成を伝える社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012616"},{"id":"00012617","register_sub_id":"101","register_pk":"367911","name":"長田神社神門","kana":"ながたじんじゃしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目101","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、銅板葺、間口3.3m","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0251","desc":"境内正面の参道上に西面して建つ銅板葺の薬医門。間口三・三メートルで、扉を設けず、本柱を丸柱とする独特の構成で、木太い軸部に一軒小舞打で軒の出の大きい屋根をかける。装飾は少ないが、総檜造の簡潔かつ豪放な表門で、境内正面の景観を厳かに引締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012617"},{"id":"00012615","register_sub_id":"101","register_pk":"367909","name":"長田神社透塀","kana":"ながたじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目101","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造、銅板葺、延長41m","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0249","desc":"本殿の四周を結界する木造銅板葺の透塀。基壇は三段の切石積、腰は縦板張目板打、腰長押と内法長押を廻し、腰上は菱形断面の板連子とする。屋根は腕木を出して桁を通し、深い軒をつくる。檜の良材を用いた精巧なつくりで、本殿周辺の景観を格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012615"},{"id":"00012614","register_sub_id":"101","register_pk":"367908","name":"長田神社中門","kana":"ながたじんじゃちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目101","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造、銅板葺、間口2.4m","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0248","desc":"本殿を囲む透塀の正面中央に建つ切妻造銅板葺妻入の門。間口二・四メートル、礎盤上の4本の丸柱を貫と長押で固め、中備蟇股、舟肘木で梁桁を受け、格天井を張る。妻飾は豕叉首、軒は一軒で起り屋根とする。明治時代の「制限図式」の影響がみられる神社建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012614"},{"id":"00012619","register_sub_id":"101","register_pk":"367913","name":"長田神社手水舎","kana":"ながたじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目121","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造、瓦葺、面積7.0㎡","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0253","desc":"神門前方の参道を挟んで祈祷殿と対面する位置に建つ。桁行2･9メートル梁間2･4メートル、四方吹放しの切妻造桟瓦葺で、礎石上の几帳面取角柱を内法虹梁で固め、柱上の舟肘木と波形蟇股で軒桁を受ける。祈祷殿と同じく門前の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012619"},{"id":"00012613","register_sub_id":"101","register_pk":"367907","name":"長田神社幣拝殿","kana":"ながたじんじゃへいはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目101","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"江戸後期／大正13年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、金属板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0247","desc":"本殿正面に西面して建つ。桁行三間梁間二間、入母屋造平入の拝殿背面に、桁行二間梁間一間、入母屋造の幣殿を出し、周囲に縁を廻す。拝殿は12畳、幣殿は6畳で床を一段高く張る。柱を角柱とし、装飾を控えた簡明なつくりで森厳な社頭景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012613"},{"id":"00012612","register_sub_id":"101","register_pk":"367906","name":"長田神社本殿","kana":"ながたじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目101","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"江戸後期／大正13年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0246","desc":"鳥取城南隣に鎮座し、本殿は境内奥に西面して建つ。正面千鳥破風付の入母屋造、正面一間、側面二間背面二間の四周に高欄付の縁を廻し、軒唐破風付の向拝を設ける。軒廻りは隅のみ出組の二軒繁垂木。向拝の打越垂木を緩やかに起らすなど優美な造形をもつ社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012612"},{"id":"00008165","register_sub_id":"101","register_pk":"132606","name":"南菀寺山門","kana":"なんえんじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県東伯郡三朝町大字三朝字下平205-3","lat":35.41175731,"lng":133.89470497,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積9.5㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"31 － 0162","desc":"市街地から庫裏に至る石段の途中に建ち、桁行一間梁間一間、楼門、入母屋造桟瓦葺である。下階を漆喰塗で厚く覆って通路をアーチ状につくり、上階は四面とも竪格子とし、軒は二軒繁垂木で、棟に鵄尾を上げる。いわゆる竜宮造の形式で、特異な伽藍景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008165"},{"id":"00010341","register_sub_id":"101","register_pk":"199114","name":"摩尼寺山門","kana":"まにじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市覚寺624","lat":35.52965822,"lng":134.26331192,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.9m、左右袖塀及び潜り戸付","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"31-0197","desc":"本堂正面に建つ一間一戸薬医門。五平の本柱と控柱上に各々冠木を渡し、皿斗付の三斗で木鼻付の梁を受け、波紋彫刻の笈形付大瓶束で棟木を受ける。屋根は切妻造桟瓦葺で棟端に鯱を載せ、破風拝みに三花懸魚を吊る。随所に立体的な彫刻を施し境内の表構えを飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010341"},{"id":"00010340","register_sub_id":"101","register_pk":"199113","name":"摩尼寺鐘楼","kana":"まにじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市覚寺624","lat":35.529561,"lng":134.263356,"geo_status":"db","era":"明治25年","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造、瓦葺、面積16㎡","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"31-0196","desc":"山門の東に建つ方一間の吹放ち形式の鐘楼で、入母屋造桟瓦葺である。几帳面取角柱を石礎盤上に内転びで立て、足固貫、内法貫、木鼻付頭貫及び台輪で固め三斗実肘木で梁を受け、中備は蟇股とする。中央に梁を渡し梵鐘を吊る。山門とともに表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010340"},{"id":"00010339","register_sub_id":"101","register_pk":"199112","name":"摩尼寺本堂","kana":"まにじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市覚寺624","lat":35.529763,"lng":134.263466,"geo_status":"db","era":"万延元年（1860）","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"31-0195","desc":"南面し、桁行三間梁間四間、入母屋造桟瓦葺で正面に千鳥破風を飾り、軒唐破風付の一間向拝を付す。正面一間を外陣とし、堂内後寄りに仏壇を据えて内陣を広くとる。向拝や内外陣境、仏壇廻りは龍や鳥獣、雲や波形の彫刻で高密度に飾り、時代的特徴を良く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010339"},{"id":"00005494","register_sub_id":"101","register_pk":"106482","name":"向山神社籠堂","kana":"むこうやまじんじゃこもりどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字市瀬","lat":35.29114092,"lng":134.24891859,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、鉄板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0099","desc":"本殿の西側にある。南を正面とする切妻造，妻入で，土台を廻して角柱を立てて貫で緊結し，竪板壁とする。南面の出入口は引込戸を設け，内側を踏込土間とする。内部は天井を張らず，板敷で囲炉裏を設ける。素朴な形式であるが，神社信仰の一端を物語る施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005494"},{"id":"00005493","register_sub_id":"101","register_pk":"106481","name":"向山神社拝殿及び覆殿","kana":"むこうやまじんじゃはいでんおよびおおいどの","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字市瀬","lat":35.29109145,"lng":134.24899614,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0098","desc":"本殿前面にある拝殿は，切妻造，妻入，正面と背面に格子戸，中敷居を入れた両側面に板戸を配し，組物や装飾のない簡素な形式である。覆殿は，吹放しの軸部を一段高く組んで，棟を拝殿と直交させる。集落を見渡す高台にあって，存在感のある形態を見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005493"},{"id":"00005492","register_sub_id":"101","register_pk":"106480","name":"向山神社本殿","kana":"むこうやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字市瀬","lat":35.29113252,"lng":134.24899614,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0097","desc":"ほぼ南面して建つ一間社流造。石造亀腹上に廻した土台上に軸部を組み，組物は三斗，中備蟇股とする。虹梁や手挟などの絵様装飾が豊かで，獅子鼻は立体的な造形である。軒は正面が二軒繁垂木，銅板葺である。近世以来の伝統的な形式と造形をよく継承している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005492"},{"id":"00011553","register_sub_id":"101","register_pk":"210389","name":"医光寺中門","kana":"いこうじちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県益田市染羽町ロ195-1","lat":34.67986111,"lng":131.86549694,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口4.6m","structure_material":"木造","registered":"2017.05.02(平成29.05.02)","register_no":"32-0180","desc":"医光寺は市街地の東部に位置する臨済宗寺院。中門は四脚門で、切妻造、桟瓦葺とする。本柱は丸柱、控柱は角柱とし、頭貫で固め、出組組物で軒を支える。頭貫に亀甲紋を地紋彫りし、虹梁や木鼻など随所を彫刻で華やかに飾り、境内景観を特徴づけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011553"},{"id":"00010888","register_sub_id":"101","register_pk":"201723","name":"出雲大社宇迦橋大鳥居","kana":"いずもおおやしろうがばしおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県出雲市大社町杵築南1387-5他","lat":35.39158,"lng":132.687275,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"鉄筋コンクリート造、高さ23m、幅14m","structure_material":"鉄筋コンクリート造","registered":"2015.11.17(平成27.11.17)","register_no":"32 ‐ 0175","desc":"高さ二三メートル、基部柱間一四メートル、柱径一・八メートルを測る巨大な鉄筋コンクリート造の明神鳥居で、宇迦橋北詰に道路を跨いで建つ。旧大社駅から出雲大社に向かう神門通りに建てられた鳥居で、近代に整備された参道景観を象徴的に演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010888"},{"id":"00010887","register_sub_id":"101","register_pk":"201722","name":"出雲大社彰古館","kana":"いずもおおやしろしょうこかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県出雲市大社町杵築東195","lat":35.402534,"lng":132.684991,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、銅板葺、建築面積165㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"32 ‐ 0174","desc":"本殿の北西方にある宝物館。亀甲積基壇に建つ木造二階建、入母屋造銅板葺で、正面中央に一間切妻造の玄関を設け、二階は桁行梁間とも側廻り一間を逓減し、縁高欄を廻して安定した外観をつくる。良質のスギ材を用い、施工も丁寧で、境内空間と調和している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010887"},{"id":"00009665","register_sub_id":"101","register_pk":"194661","name":"櫛代賀姫神社本殿","kana":"くししろかひめじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県益田市久城町963-1他","lat":34.70126748,"lng":131.84003628,"geo_status":"db","era":"明和2","year":1765,"year_source":"db","year_min":1765,"year_max":1765,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"32 － 0167","desc":"拝殿後方に建つ三間社流造銅板葺で、庇部床高を本屋より一段下げて縁高欄を廻らし、庇の側面に格子をたてて前室風につくる。妻飾は豕扠首で軒は一軒繁垂木とする。当地方の神社本殿の特徴を示すとともに、細部に天正期の古材を残し、遺風を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009665"},{"id":"00000086","register_sub_id":"101","register_pk":"101076","name":"津和野カトリック教会","kana":"つわのかとりっくきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県鹿足郡津和野町大字後田ロ66-7","lat":34.46746341,"lng":131.77412759,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積131㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"32 － 0005","desc":"この教会は，長崎浦上のキリシタン信徒の殉教地として知られる津和野にビリオン神父によって創設されたもので，現在の建物は昭和４年の再建である。木造平屋建の単塔式のゴシック様式になり，簡潔な図柄のスデンドグラスのある教会として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000086"},{"id":"00008364","register_sub_id":"101","register_pk":"134006","name":"津和野カトリック教会神父館","kana":"つわのかとりっくきょうかいしんぷかん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県鹿足郡津和野町後田字殿町ロ66-7","lat":34.46731759,"lng":131.77415663,"geo_status":"db","era":"昭和6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、スレート葺、建築面積69㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0156","desc":"和風庭園に西面して建つ。桁行１３ｍ梁間５．４ｍの木造２階建。寄棟造スレート葺とし、外壁は２階を下見板張、１階を腰板張、上部を板壁ペンキ塗装とする。内部は１階に事務室や応接室、食堂、２階に居室三室などを配する。地方における教会施設の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008364"},{"id":"00014293","register_sub_id":"101","register_pk":"509683","name":"美保神社拝殿","kana":"みほじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市美保関町美保関608","lat":35.56231944,"lng":133.30629167,"geo_status":"db","era":"大正13年／平成10年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、杮葺、建築面積203㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"32 - 0216","desc":"美保関に位置する式内社の拝殿。桁行六間、梁間三間、切妻造妻入杮葺で、正面の下屋中央に切妻の破風を付す。内部は石敷で柱が林立し、柱間装置は四面開放で、天井を張らずに整然とした小屋組をみせる。いわゆる美保造の雄大な本殿に相応しい広壮な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014293"},{"id":"00000083","register_sub_id":"101","register_pk":"101073","name":"横田相愛教会（旧救世軍会館）","kana":"よこたそうあいきょうかい（きゅうきゅうせいぐんかいかん）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県仁多郡奥出雲町横田924","lat":35.17981391,"lng":133.0906053,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建塔屋付、亜鉛メッキ銅板葺、建築面積155㎡","structure_material":"木造2階建塔屋付","registered":"1996.12.20(平成8.12.20)","register_no":"32 － 0002","desc":"桁行１１間，梁間７間の規模の木造２階建の教会で，正面に出入り口を兼ねた４階建ての塔屋が取り付く。地元の求道者岡崎喜一郎が私財を投じて建築にあたったという。外壁を下見板張りとし，特徴的な窓枠を備えた素朴な洋風の教会である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000083"},{"id":"00012988","register_sub_id":"101","register_pk":"368067","name":"大浦神社鳥居","kana":"おおうらじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県浅口市寄島町7756-1","lat":34.48113611,"lng":133.58216111,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"石造、間口4.5m","structure_material":"石造","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 329","desc":"境内東方に延びる参道入口に建つ花崗石製明神鳥居。柱間4・5メートル高さ6・5メートル、足元径0・6メートルの円柱を頂部で柱1本分の内転びで立て、貫で固め、反りのある島木笠木を載せる。均整の取れた外観で参道景観の核をなし、参拝者に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012988"},{"id":"00012987","register_sub_id":"101","register_pk":"368066","name":"大浦神社祝詞殿、幣殿及び拝殿","kana":"おおうらじんじゃのりとでん、へいでんおよびはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県浅口市寄島町7756-1","lat":34.48166111,"lng":133.58136667,"geo_status":"db","era":"昭和2年頃／平成21年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 328","desc":"本殿前に東面して建つ。入母屋造銅板葺の拝殿と祝詞殿を前後に並べ、両下造の幣殿でつなぐ権現造風の外観で、拝殿正面に千鳥破風と大振りの向唐破風向拝を付す。全体に簡明ながら端正なつくりで、向拝を霊獣の彫刻で飾るなど、厳かな社頭景観を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012987"},{"id":"00012986","register_sub_id":"101","register_pk":"368065","name":"大浦神社本殿","kana":"おおうらじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県浅口市寄島町7756-1","lat":34.48180278,"lng":133.58121111,"geo_status":"db","era":"昭和2年／平成27年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 327","desc":"市南部の寄島町中心部にある神社。本殿は境内後方の高い基壇上に東面して建つ。桁行三間梁間三間、入母屋造銅板葺、正面千鳥破風、向拝一間軒唐破風付。組物は尾垂木付二手先とし、蟇股や木鼻に精巧な彫刻を施すなど、端正な意匠でまとめた近代の大型本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012986"},{"id":"00015234","register_sub_id":"101","register_pk":"530658","name":"大元宗忠神社御札所（旧神札殿）","kana":"おおもとむねただじんじゃおふだしょ（きゅうみまもりどの）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.645175,"lng":133.90185278,"geo_status":"db","era":"明治18年／昭和52年・平成3年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、銅板葺、建築面積48㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0376","desc":"拝殿の南東に位置する入母屋造銅板葺東西棟の御札所。組物は木鼻付大斗肘木で軒は一軒繁垂木とする。かつて木階を付した北正面に庇を架け、身舎周囲に刎高欄付の切目縁を廻す。内部は１室で御札所とする。社務所と一対で左右対称の境内景観をつくる御札所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015234"},{"id":"00015237","register_sub_id":"101","register_pk":"530661","name":"大元宗忠神社教祖記念館（旧布教所兼主屋）","kana":"おおもとむねただじんじゃきょうそきねんかん（きゅうふきょうしょけんおもや）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-102","lat":34.64498611,"lng":133.90212222,"geo_status":"db","era":"嘉永元年(1848)／明治15年移築、平成16年改修","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、茅葺一部瓦葺、建築面積274㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0379","desc":"境内南東に位置するかつての布教所兼主屋。入母屋造茅葺で周囲に本瓦葺の下屋を廻し、南面に大玄関を突出する。西側に神壇と旧祖霊社を配し、六室に区切る三六畳半の教場が中央を占める。北西に教祖宗忠が晩年居住した御居間を残し、黒住教の記念碑的な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015237"},{"id":"00015233","register_sub_id":"101","register_pk":"530657","name":"大元宗忠神社社務所（旧神饌殿）","kana":"おおもとむねただじんじゃしゃむしょ（きゅうみけどの）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64555,"lng":133.90185833,"geo_status":"db","era":"明治18年／昭和52年・平成元年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、銅板葺、建築面積46㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0375","desc":"拝殿の北東に位置する、入母屋造銅板葺東西棟の社務所。組物は木鼻付大斗肘木で、軒は一軒繁垂木とする。かつて木階を付した南正面に庇を付し、身舎周囲には刎高欄付の切目縁を廻す。内部は一室で宮司室。御札所と一対で左右対称の境内景観をつくる社務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015233"},{"id":"00015239","register_sub_id":"101","register_pk":"530663","name":"大元宗忠神社長屋門","kana":"おおもとむねただじんじゃながやもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-103","lat":34.64484722,"lng":133.90233611,"geo_status":"db","era":"江戸末期／昭和55年頃・平成7年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0381","desc":"教祖記念館の南東、通りに東面して建つ長屋門。北面切妻造、南面入母屋造、本瓦葺で、南・西面に下屋を廻らす。中央南寄りに板扉の門口を構えて石敷土間とし、北脇に潜戸を設ける。外壁は腰高の焼杉板張。旧布教所兼主屋の正門となる堅実なつくりの長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015239"},{"id":"00015232","register_sub_id":"101","register_pk":"530656","name":"大元宗忠神社拝殿","kana":"おおもとむねただじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64536389,"lng":133.90172778,"geo_status":"db","era":"明治18年／昭和52年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積262㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0374","desc":"本殿の東に建つ比翼入母屋造銅板葺の大規模拝殿。正面に千鳥破風、唐破風造の向拝を付す。内部は御神前の両脇に幣殿を配し、東は長大な虹梁で柱を省いた広大な教場とし、御神前へと床高を高める。向拝廻りを豊富に装飾し、華やかかつ独特の外観を備えた拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015232"},{"id":"00015235","register_sub_id":"101","register_pk":"530659","name":"大元宗忠神社拝殿北回廊","kana":"おおもとむねただじんじゃはいでんきたかいろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64548889,"lng":133.90176111,"geo_status":"db","era":"明治18年／昭和52年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0377","desc":"拝殿と社務所を接続する回廊。平面矩折の両下造銅板葺の渡廊下で北面に武道館への渡廊下が接続。柱を胴差で繋ぎ、床を高く張り、腰と内法上部は竪板張。床は拭板敷、天井は竿縁天井。南回廊と対をなし、拝殿、御札所、社務所とともに社殿の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015235"},{"id":"00015236","register_sub_id":"101","register_pk":"530660","name":"大元宗忠神社拝殿南回廊","kana":"おおもとむねただじんじゃはいでんみなみかいろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64521111,"lng":133.90176667,"geo_status":"db","era":"明治18年／昭和52年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0378","desc":"拝殿と御札所を接続する回廊。平面矩折とする両下造銅板葺の渡廊下で、柱を胴差で繋ぎ、床を高く張り、腰と内法上部は竪板張、床は拭板敷、天井は竿縁天井。隅部の床下は物置とする。北回廊と対をなし、拝殿、御札所、社務所とともに社殿の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015236"},{"id":"00015238","register_sub_id":"101","register_pk":"530662","name":"大元宗忠神社武道館（旧大教会所）","kana":"おおもとむねただじんじゃぶどうかん（きゅうだいきょうかいしょ）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64579444,"lng":133.90159444,"geo_status":"db","era":"明治32年／大正2年増築、昭和51年・平成16年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積616㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0380","desc":"本殿の北方に東面して建つかつての布教の中心道場。入母屋造妻入桟瓦葺の周囲に下屋を廻し、正面に入母屋造玄関を付す。内部中央は一室の広大な板敷で、西面を上段とし、奥に旧神壇を張出す。木造トラスを用いて二〇〇畳に及ぶ無柱空間を実現した大規模道場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015238"},{"id":"00015231","register_sub_id":"101","register_pk":"530655","name":"大元宗忠神社本殿","kana":"おおもとむねただじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64536667,"lng":133.90143056,"geo_status":"db","era":"明治18年／昭和39年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0373","desc":"ＪＲ大元駅西方、黒住教発祥地に教祖大元宗忠を祀った神社本殿。基壇上に建つ入母屋造銅板葺社殿で、正面に千鳥破風を据え、三間の向拝に軒唐破風を付し、床高の高い身舎周囲に縁を廻す。伝統的な彫刻や錺金具で荘厳し、細部まで丁寧なつくりの上質な本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015231"},{"id":"00015240","register_sub_id":"101","register_pk":"530664","name":"大元宗忠神社門及び瑞垣","kana":"おおもとむねただじんじゃもんおよびみずがき","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64537222,"lng":133.90152778,"geo_status":"db","era":"明治18年／昭和39年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"門 木造、銅板葺、間口2.2m 瑞垣 木造、銅板葺、総延長62m","structure_material":"門 木造","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0382","desc":"本殿正面に開く門及び周囲を廻る瑞垣。門は銅板葺の平唐門で、礎盤上に円柱を立て、桟唐戸を開く。冠木上中央に浪に兎の彫刻を飾る。塀は切妻造銅板葺で、精緻に積んだ切石積の基壇上に建ち、柱間に菱格子と襷桟の欄間を嵌める。本殿を区画する上質な門と塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015240"},{"id":"00012029","register_sub_id":"101","register_pk":"210970","name":"木山神社拝殿","kana":"きやまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県真庭市木山字金谷平1265-1","lat":35.016837,"lng":133.722298,"geo_status":"db","era":"大正8年／昭和37年移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"33-282","desc":"大正八年に現在の奥宮の場所で建てられ、昭和三七年に現在の里宮に移築されたもの。設計は江川三郎八。入母屋造銅板葺で小屋組をトラスとし、唐破風造の三間向拝が取り付く。吹寄垂木の多用、たすき状の意匠など、江川の作品に特徴的な要素を多く見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012029"},{"id":"00012030","register_sub_id":"101","register_pk":"210971","name":"木山神社渡廊下","kana":"きやまじんじゃわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県真庭市木山字金谷平1265-1","lat":35.016714,"lng":133.722329,"geo_status":"db","era":"大正8年／昭和37年移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"33-283","desc":"拝殿の南面東端部と社務所を結ぶ渡廊下。両下造銅板葺で、床に緩やかな起りを付け、高欄を配する。桁行方向各柱間には虹梁をかけ、妻部分にも湾曲の大きい虹梁をかけて、随所を彫刻で飾る。軒の垂木を吹寄せとするなど、拝殿と共通する意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012030"},{"id":"00012236","register_sub_id":"101","register_pk":"353036","name":"弘泉寺山門","kana":"こうせんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市下津井田之浦二丁目843","lat":34.437726,"lng":133.804996,"geo_status":"db","era":"文政12年(1829）","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"33-295","desc":"境内東寄りに建つ山門。塩飽大工の手になるもので、本瓦葺の薬医門。両脇にも門口を設けて、二軒繁垂木とする重厚な門であり、頭貫は全長に渡って波を模しているなど、随所に彫刻を彫る装飾豊かな点が特徴。地域及び大工の特色をよく表出した門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012236"},{"id":"00012235","register_sub_id":"101","register_pk":"353035","name":"弘泉寺本堂","kana":"こうせんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市下津井田之浦二丁目843","lat":34.437734,"lng":133.804735,"geo_status":"db","era":"文政10年(1827)／昭和51年改修","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"33-294","desc":"塩飽大工の手になるもので、東面して建つ。桁行三間、梁間四間、向拝一間、入母屋造桟瓦葺で、石垣基壇上に青木石の亀腹基礎を設けている。良材を用いた手堅い造りで、蟇股など細部意匠は波形や動植物の洗練された意匠で飾り、地域の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012235"},{"id":"00012639","register_sub_id":"101","register_pk":"367933","name":"金光教教学研究所客殿","kana":"こんこうきょうきょうがくけんきゅうしょきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県浅口市金光町大谷1441-3他","lat":34.529953,"lng":133.629623,"geo_status":"geocoded","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積349㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0304","desc":"金光町市街南部の丘上にある迎賓施設で、客殿は敷地中央に西面して建つ。平屋建、南北棟の入母屋造銅板葺で四周に下屋を廻す。内部は中廊下を矩折れに通して椅子坐式の座敷4室を設ける。近代の設計手法と伝統木造技術が高度に調和した昭和期和風建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012639"},{"id":"00012640","register_sub_id":"101","register_pk":"367934","name":"金光教教学研究所客殿付属舎","kana":"こんこうきょうきょうがくけんきゅうしょきゃくでんふぞくしゃ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県浅口市金光町大谷1441-3他","lat":34.529953,"lng":133.629623,"geo_status":"geocoded","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積131㎡、渡廊下付","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0305","desc":"客殿前方北寄りに南面して建つ。平屋建、入母屋造銅板葺で、正面に入母屋造の玄関を突出する。南東隅から東と南に渡廊下を延ばして、客殿、洋館と接続する。内部は前半に玄関や控室、後半に厨房や浴室等を設ける。客殿と一体をなす上質なつくりの和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012640"},{"id":"00012641","register_sub_id":"101","register_pk":"367935","name":"金光教教学研究所洋館","kana":"こんこうきょうきょうがくけんきゅうしょようかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県浅口市金光町大谷1441-3他","lat":34.529953,"lng":133.629623,"geo_status":"geocoded","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、スレート葺、建築面積208㎡、渡廊下付","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0306","desc":"客殿前方南側に西面して建つ。木造二階建、寄棟造で西南隅に塔屋を設け、正面に玄関ポーチを付す。外壁は人造石洗出し仕上、半円窓やメダイヨンで要所を飾る。一階に応接間等各室、二階に大広間を設ける。客殿と相対し、格調高い和洋館併設の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012641"},{"id":"00012984","register_sub_id":"101","register_pk":null,"name":"西大寺石門","kana":"さいだいじいしもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65323333,"lng":134.03787778,"geo_status":"db","era":"文政2年(1819)","year":1819,"year_source":"db","year_min":1819,"year_max":1819,"year_label":null,"structure":"石造及び木造2階建、瓦葺、建築面積31㎡","structure_material":"石造及び木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 325","desc":"境内南面中央に建つ入母屋造本瓦葺の竜宮造楼門。下層は石造で、四隅に石柱を立てて上部にアーチ状の石梁を渡す。上層は木造で各間に花頭窓を開く。組物はなく一軒扇垂木で、外壁を軒裏まで漆喰で塗込める。下層石造の豪壮な竜宮造で、国内最大規模を誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012984"},{"id":"00012982","register_sub_id":"101","register_pk":null,"name":"西大寺経蔵（輪蔵）","kana":"さいだいじきょうぞう（りんぞう）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65346111,"lng":134.03743056,"geo_status":"db","era":"嘉永7年（1854)／大正期移築","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 323","desc":"境内西南辺に東面して建つ。六角形平面の本瓦葺で、正面の扉口に片流れの向拝を付す。軒は出桁造で、外壁は軒裏まで漆喰で塗込める。内部中央の八角輪蔵は総欅造で、尾垂木付三手先詰組や軒扇垂木など禅宗様とする。輪蔵を備えた六角経蔵の貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012982"},{"id":"00012981","register_sub_id":"101","register_pk":null,"name":"西大寺高祖堂","kana":"さいだいじこうそどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65376389,"lng":134.03757778,"geo_status":"db","era":"安永9年(1780)頃","year":1780,"year_source":"db","year_min":1780,"year_max":1780,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 322","desc":"吉井川下流西岸にある真言宗寺院。高祖堂は境内西北隅に南面して建つ。方三間、宝形造本瓦葺で、正側面に高欄付縁を廻す。内部は畳敷の一室で、奥に須弥壇を置き、二重折上小組格天井を張る。組物は出組、中備は蟇股。装飾を控えた格式の高いつくりをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012981"},{"id":"00011555","register_sub_id":"101","register_pk":"210490","name":"西大寺牛玉所殿奥殿","kana":"さいだいじごおしょでんおくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65431111,"lng":134.03838611,"geo_status":"db","era":"明治2年","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.2㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"33-0277","desc":"本殿・釣殿及び拝殿の奥に南面して建つ。一間社、宝形造、本瓦葺で、本殿背後の石垣上の高い位置にあり、一時期本殿とされていた。軒は二軒繁垂木で、一間四方の小ぶりな社殿であるが、三方に縁を廻らし、脇障子を設け、向拝周り、組物等に濃密な意匠を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011555"},{"id":"00011554","register_sub_id":"101","register_pk":"210489","name":"西大寺牛玉所殿本殿・釣殿及び拝殿","kana":"さいだいじごおしょでんほんでん・つりどのおよびはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65408694,"lng":134.038325,"geo_status":"db","era":"明治13年","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積241㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"33-0276","desc":"邑久大工の作になる複合社殿で、拝殿、本殿とも入母屋造本瓦葺。本殿上には楼閣を設ける。拝殿は三手先、本殿は二手先で、本殿は二軒で地を並行垂木、飛檐を扇垂木とする珍しい形式。本殿天井は未完であり、楼閣を支える複雑な小屋組を見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011554"},{"id":"00012985","register_sub_id":"101","register_pk":null,"name":"西大寺鐘楼門","kana":"さいだいじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65386389,"lng":134.03781667,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積10㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 326","desc":"境内を南北に区切る土塀中央に建つ入母屋造本瓦葺の一間楼門。下層は正背面に虹梁を渡し、親柱筋に板扉を備える。上層は正背三間として中央間を開放し、梵鐘を吊る。組物は出組、中備は間斗束、縁腰組は出三斗。江戸中期の境内の建築形式を伝える遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012985"},{"id":"00012983","register_sub_id":"101","register_pk":null,"name":"西大寺仁王門","kana":"さいだいじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65359444,"lng":134.03750556,"geo_status":"db","era":"元文5年（1740）頃","year":1740,"year_source":"db","year_min":1740,"year_max":1740,"year_label":null,"structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 324","desc":"境内西面北寄りに建つ。入母屋造本瓦葺の三間一戸楼門で、正面両脇間の金剛柵後方に仁王像を安置する。上層は尾垂木付三手先、中備蟇股とし、縁腰組は四手先で四周琵琶板に十二支を彫刻する。精緻な大工技術を駆使した禅宗様で、規模雄大な楼門の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012983"},{"id":"00013183","register_sub_id":"101","register_pk":"368407","name":"実際寺客殿","kana":"じっさいじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市中島字村内北町516","lat":34.58624444,"lng":133.73464167,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（金属板仮葺）、建築面積103㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"33 － 0331","desc":"本堂の北東に建つ。庫裏の接客部が残ったものとみられ、桁行５間、梁間４間での三方廊下に縁を廻らす。入母屋造茅葺金属板仮葺で、三方に本瓦葺の下屋を廻す。内部は南列は西から８畳と１２畳、北列は座敷７畳、板間、８畳で、座敷には床と付書院を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013183"},{"id":"00013186","register_sub_id":"101","register_pk":"368410","name":"実際寺山門","kana":"じっさいじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市中島字村内北町516","lat":34.58608611,"lng":133.73482222,"geo_status":"db","era":"明治17年","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造、瓦葺、間口2.6m、左右袖塀付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"33 － 0334","desc":"境内南東に南面して建ち、切妻造本瓦葺の薬医門で袖塀として本瓦葺の土塀が付く。本柱は五平で、冠木を載せ、女梁、男梁と組み、出三斗組で桁と梁を支持する。妻は虹梁蟇股で、棟木下に拳鼻を付し、軒は一軒疎垂木である。江戸後期に遡る重厚な山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013186"},{"id":"00013184","register_sub_id":"101","register_pk":"368408","name":"実際寺鐘楼","kana":"じっさいじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市中島字村内北町516","lat":34.58605556,"lng":133.73464722,"geo_status":"db","era":"明治12年／大正15年移築","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造、瓦葺、面積3.8㎡","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"33 － 0332","desc":"本堂の南東に建つ。方一間の鐘楼で屋根は入母屋造本瓦葺で、近世部材を再用した鐘楼である。四方転びの角柱を腰貫、飛貫、頭貫で固め、腰貫は撞木を吊る東側を一段下げる。組物は柱上で枠肘木の三斗組とし、軒は一軒疎垂木である。妻は菱格子とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013184"},{"id":"00013187","register_sub_id":"101","register_pk":"368411","name":"実際寺外塀及び石垣","kana":"じっさいじそとべいおよびいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市中島字村内北町516","lat":34.58634444,"lng":133.73483611,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"外塀 木造、瓦葺、延長61m 石垣 石造、延長71m","structure_material":"外塀 木造","registered":"2019.12.05(令和1.12.05)","register_no":"33 － 0335","desc":"敷地東辺から北辺に廻る。外塀は腕木付桟瓦屋根の土塀が納屋北東角から北に延び北東角隅で西へ折れ、北辺では一段低い瓦葺築地塀となる。石垣の東面は乱積で、納屋基礎部と北辺は谷積となる。境内の外周を整える施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013187"},{"id":"00013185","register_sub_id":"101","register_pk":"368409","name":"実際寺納屋","kana":"じっさいじなや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市中島字村内北町516","lat":34.58613333,"lng":133.73488333,"geo_status":"db","era":"明治17年頃","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階建、瓦葺、建築面積46㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"33 － 0333","desc":"境内の東辺南寄りに西面して建つ。桁行５間、梁間２間の南北棟で、南側を入母屋造、北側を切妻造とし西面の下屋とも本瓦葺とする。外壁は大壁漆喰塗で、外廻りは焼板竪板張とする。１階は土間の３室、２階は板間の二室に仕切る。境内導入部の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013185"},{"id":"00013182","register_sub_id":"101","register_pk":"368406","name":"実際寺本堂","kana":"じっさいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市中島字村内北町516","lat":34.58613889,"lng":133.73456944,"geo_status":"db","era":"慶安2年（1649）／明治前期・昭和59年改修","year":1649,"year_source":"db","year_min":1649,"year_max":1649,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"33 － 0330","desc":"境内西に東面して建つ小規模な真言宗寺院の本堂。正面３間、側面２間で、正面と南側面に切目縁を廻らし、柱は全て角柱で面取が大きく、縁外に軒支柱を建て、身舎柱筋大斗上の海老虹梁で縁桁と繋ぐ。木鼻や実肘木の渦も江戸前期らしい特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013182"},{"id":"00012032","register_sub_id":"101","register_pk":"210973","name":"善覚稲荷神社拝殿","kana":"ぜんかくいなりじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県真庭市木山字金谷平1265-1","lat":35.016978,"lng":133.722436,"geo_status":"db","era":"大正8年／昭和37年移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"33-285","desc":"本社拝殿の右方に並んで建つ。妻入の入母屋造銅板葺で、背面右方に神饌所、本殿との間に釣殿が附属する。江川三郎八の設計になり、吹寄垂木、特徴あるトラス架構、格天井など、その特徴をよく示す他、正面側基礎石を洋風意匠とするなど特徴ある意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012032"},{"id":"00012031","register_sub_id":"101","register_pk":"210972","name":"善覚稲荷神社本殿","kana":"ぜんかくいなりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県真庭市木山字金谷平1265-1","lat":35.017,"lng":133.72234,"geo_status":"db","era":"大正8年／昭和37年移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"33-284","desc":"桁行四･〇メートル、梁間三・二メートル、切妻造銅板葺、平入で、四周に縁を廻らす。壁を二重に張り、柱は外側を円柱、内側を角柱とし、天井は格天井。設計は江川三郎八で、垂木を吹寄とするなど、境内の他の建物と共通する要素でまとめる、特色ある社殿建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012031"},{"id":"00004183","register_sub_id":"101","register_pk":"105173","name":"天仲院本堂","kana":"てんちゅういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野251","lat":34.68128272,"lng":133.72922579,"geo_status":"db","era":"文政11","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"33 － 0090","desc":"田園地帯に南面して建つ。桁行約１４ｍ，入母屋造，本瓦葺で，側廻りには角柱を立て，舟肘木で軒を受ける。平面は正面広縁付，座敷を西北隅に配した６間取で，いわゆる方丈形式とする。棟札から建築年代が明らかで，地方における江戸後期の臨済宗本堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004183"},{"id":"00008764","register_sub_id":"101","register_pk":"149485","name":"洞松寺開山堂及び位牌堂","kana":"とうしょうじかいざんどうおよびいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59030389,"lng":133.62003585,"geo_status":"db","era":"享保年間（1716-1735）／江戸末期・明治前期・昭和後期改修","year":1726,"year_source":"estimated","year_min":1716,"year_max":1735,"year_label":"享保年間（1716-1735）","structure":"木造平屋建、鉄板葺一部瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0241","desc":"本堂の内陣後方に位牌堂を介して開山堂を建てる。開山堂は6.8ｍ四方で、宝形造鉄板葺とし、後方に壇を設けて開山を祀る。また位牌堂は桁行3.8ｍ梁間5.1ｍ、両下造瓦葺で、両側に位牌壇を設置。本堂建立後に開山堂や位牌堂が整備された経過を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008764"},{"id":"00008767","register_sub_id":"101","register_pk":"149488","name":"洞松寺庫裏","kana":"とうしょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59042017,"lng":133.61956045,"geo_status":"db","era":"宝暦2年(1752)／天保14年(1843)増築・平成9年改修","year":1752,"year_source":"converted","year_min":1752,"year_max":1752,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積296㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0244","desc":"方丈北側に接続し、桁行28ｍ梁間12ｍ、入母屋造及び切妻造桟瓦葺で、北端の浴司を落棟とする。中央の広い土間正面に桟唐戸を開き、典座寮等を配す。地方禅院における庫裏の好例であり、相対して建つ禅堂とともに、禅院の伽藍構成をよくとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008767"},{"id":"00008769","register_sub_id":"101","register_pk":"149490","name":"洞松寺書院月泉院","kana":"とうしょうじしょいんげっせんいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59078484,"lng":133.61973231,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0246","desc":"禅堂北側の一郭に、南面して建つ。桁行11ｍ梁間7.5ｍ、入母屋造本瓦葺で妻壁を菱格子とし、周囲に桟瓦葺の下屋をめぐらす。内部は客間と仏間のほか、茶室、台所などからなり、造作にも良材を用いる。風格を備えた、住職の居住施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008769"},{"id":"00008768","register_sub_id":"101","register_pk":"149489","name":"洞松寺鐘楼","kana":"とうしょうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59050589,"lng":133.61994201,"geo_status":"db","era":"天保9年（1838）","year":1838,"year_source":"converted","year_min":1838,"year_max":1838,"year_label":null,"structure":"木造2階建、瓦葺、建築面積18㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0245","desc":"本堂と接賓を繋ぐ位置に建つ。桁行5.3ｍ梁間4/0ｍ、両下造桟瓦葺の下層に、正方形平面で入母屋造本瓦葺の上層を、棟を直交させて載せる。上層は壁に花頭窓を開けて縁高欄をめぐらし、頭貫には渦紋を表して妻壁を菱格子とするなど、華やかな意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008768"},{"id":"00008765","register_sub_id":"101","register_pk":"149486","name":"洞松寺禅堂及び接賓","kana":"とうしょうじぜんどうおよびせっぴん","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59065616,"lng":133.61988194,"geo_status":"db","era":"天保9年（1838）","year":1838,"year_source":"converted","year_min":1838,"year_max":1838,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積251㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0242","desc":"本堂東側に鐘楼を介して建ち、南北に長い平面をもつ。桁行27ｍ梁間10ｍ、入母屋造本瓦葺で、中央を露地で仕切り、北半を禅堂として内部に単を配し、南半は禅僧の宿所である接賓とする。江戸末期における曹洞宗寺院の禅堂形式を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008765"},{"id":"00008771","register_sub_id":"101","register_pk":"149492","name":"洞松寺二ノ門","kana":"とうしょうじにのもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3774-1","lat":34.59295231,"lng":133.6194785,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0248","desc":"山門から250ｍ北方の参道に建ち、桁行3.0ｍ梁間2.7ｍ、切妻造本瓦葺である。正・背面は方柱を虹梁で繋ぎ、側面は腰下を開放とし、上部は柱筋外側を壁として内側を浅い仏壇とする。また軒先まで漆喰で塗り込めるなど、特異な形式で風格のある表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008771"},{"id":"00008766","register_sub_id":"101","register_pk":"149487","name":"洞松寺方丈及び書院","kana":"とうしょうじほうじょうおよびしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59028337,"lng":133.61974172,"geo_status":"db","era":"宝暦3年(1753)／天保6年(1835)増築・昭和54年頃改修","year":1753,"year_source":"converted","year_min":1753,"year_max":1753,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積220㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0243","desc":"境内南西に建ち、方丈が庫裏に、書院が本堂に接続し、南北14ｍ東西16ｍ、入母屋造桟瓦葺である。方丈は南側にトコを備えた座敷や茶室を配し、北側を20畳の広間とする。書院は正面に式台を構え、奥室に大トコをもつ。丁寧なつくりの接客施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008766"},{"id":"00008763","register_sub_id":"101","register_pk":"149484","name":"洞松寺本堂","kana":"とうしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.5903861,"lng":133.61989142,"geo_status":"db","era":"元禄10年(1697)／天明5年(1785)・昭和54年改修","year":1697,"year_source":"converted","year_min":1697,"year_max":1697,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積290㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0240","desc":"境内奥に北面して建ち、桁行19ｍ梁間15ｍ、入母屋造、本瓦葺及び桟瓦葺である。六間取方丈形式で、前方二間通りと西側面に広縁をとる。内陣と大間に折上天井を張り、両室境は太い円柱で二手先を受け、花頭枠を渡すなど、意匠を凝らした曹洞宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008763"},{"id":"00008770","register_sub_id":"101","register_pk":"149491","name":"洞松寺門及び土塀","kana":"とうしょうじもんおよびどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59069635,"lng":133.6193841,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"門 木造、間口1.3m 土塀 総延長75m","structure_material":"門 木造","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0247","desc":"月泉院西面に開く門と、その左右に矩折れに伸びて月泉院を囲む土塀、及び山門両側に築かれた土塀からなる。門は、1間棟門、切妻造桟瓦葺で、舞良戸を両開に吊る。土塀は総延長75ｍ、壁は漆喰で仕上げる。端正な意匠の土塀が境内景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008770"},{"id":"00013889","register_sub_id":"101","register_pk":"507847","name":"中山神社拝殿","kana":"なかやまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県津山市一宮695-2","lat":35.100175,"lng":133.99463889,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"33 － 0347","desc":"本殿が重文の神社拝殿。入母屋造檜皮葺平入で正面に唐破風向拝を付す。設計は江川三郎八。正面中央を両折板唐戸とし他は格子戸引違を建て廻らす。特異なプロポーションの扱いや、吹寄垂木や格天井、直線的な舟肘木の使用等、随所に江川の作風が看取される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013889"},{"id":"00013890","register_sub_id":"101","register_pk":"507848","name":"中山神社幣殿","kana":"なかやまじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県津山市一宮695-2","lat":35.10021944,"lng":133.99458889,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"33 － 0348","desc":"拝殿同様江川三郎八の設計。桁行一間梁間一間で、桁行は実長三間分の柱間を成の高い頭貫で支える。組物は大斗肘木で屋根は切妻造檜皮葺。柱間は全て開放とし高欄を付す。特異な吹寄垂木の船底天井は江川設計の木山神社幣殿と類似する等、その作風をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013890"},{"id":"00007586","register_sub_id":"101","register_pk":"108568","name":"日本基督教団倉敷教会教会堂","kana":"にほんきりすときょうだんくらしききょうかいきょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市鶴形1-679-1","lat":34.600658,"lng":133.77107207,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造一部コンクリート造3階建塔屋付、スレート葺、建築面積267㎡、スロープ付","structure_material":"木造一部コンクリート造3階建塔屋付","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0203","desc":"通りの西側に建つ。東西棟の切妻造スレート葺で、東南隅に塔屋を付設。１階を木骨ＲＣ造の石貼とし、長いスロープが２階礼拝堂前のテラスへと続く。礼拝堂は単廊式で側面に４ヶ所の尖頭アーチ窓を開ける。石造風の重厚さと上部の軽快さが独特の調和を生み出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007586"},{"id":"00007688","register_sub_id":"101","register_pk":"108670","name":"寶福寺秋葉宮石垣及び玉垣","kana":"ほうふくじあきばぐういしがきおよびたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野2068-4","lat":34.69163335,"lng":133.73334753,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石垣 石造、総延長37m、玉垣 石造、総延長40m、石段及び石門付","structure_material":"石垣 石造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0227","desc":"秋葉宮境内の南端を画し、境内地を造成。拝殿の南方に長い石段を設け、その両側に石垣を築く。石垣は総延長３７ｍ、高さ３．０ｍで、石段側を切石積、隅を算木積、他を野石乱積とし、上部に石製の玉垣を置く。石段は大きく３分され、途中に石門を構える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007688"},{"id":"00007686","register_sub_id":"101","register_pk":"108668","name":"寶福寺秋葉宮五社明神宮","kana":"ほうふくじあきばぐうごしゃみょうじんぐう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野2068-4","lat":34.6919216,"lng":133.73316198,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"石祠5基及び基壇からなる、石造、建築面積2.1㎡","structure_material":"石祠5基及び基壇からなる","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0225","desc":"本殿の後方、東西に長く石積基壇を造り、その上に同じ規模形式の石祠５基を並べる。石祠は正面０．６２ｍ側面０．６８ｍ規模。石製基礎石上、側・背面に石板、正面には板扉をたて、緩やかな軒反りをもつ入母屋造屋根を載せる。秋葉宮境内に落ち着きを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007686"},{"id":"00007687","register_sub_id":"101","register_pk":"108669","name":"寶福寺秋葉宮手水舎","kana":"ほうふくじあきばぐうてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野2068-4","lat":34.69173628,"lng":133.73318609,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造及び木造、鉄板葺、間口1.2m、水盤付","structure_material":"石造及び木造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0226","desc":"拝殿の南西に建つ。南北棟の切妻造鉄板葺。間口１．２ｍに石製方柱を建て、頂部に腕木を架し、その上に束を建て、棟木や軒桁を渡し、垂木を疎らに配る。柱間に長方形の水盤を置く。水盤は切石上に置かれ、底面を花頭形に切り込む。簡易な構造の手水舎の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007687"},{"id":"00007685","register_sub_id":"101","register_pk":"108667","name":"寶福寺秋葉宮拝殿及び渡殿","kana":"ほうふくじあきばぐうはいでんおよびわたりでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野2068-4","lat":34.69180349,"lng":133.73321721,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積86㎡、前後石垣及び石段付","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0224","desc":"本殿の正面に位置する。拝殿は桁行五間梁間二間、入母屋造本瓦葺で、千鳥破風と軒唐破風付一間向拝を付ける。内部は畳敷で、棹縁天井。渡殿は拝殿背面中央間から突出して設けられ、儀式の間と祭壇の間を前後に設ける。礼拝の場として整備された形態になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007685"},{"id":"00007684","register_sub_id":"101","register_pk":"108666","name":"寶福寺秋葉宮本殿","kana":"ほうふくじあきばぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野2068-4","lat":34.691898,"lng":133.73317009,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積6.1㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0223","desc":"山内北西の小高い位置に南面して建つ。桁行一間梁間一間、入母屋造本瓦葺で、正面に一間向拝を付け、周囲に組高欄付縁をまわす。円柱で二手先詰組とし、二軒繁垂木。小規模ながら、均整の取れた外観で、向拝木鼻や隅尾垂木を雲龍の丸彫とするなど、装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007684"},{"id":"00007681","register_sub_id":"101","register_pk":"108663","name":"寶福寺開山堂","kana":"ほうふくじかいざんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1973-1","lat":34.69043411,"lng":133.73449119,"geo_status":"db","era":"江戸中期／江戸後期増築・昭和35改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積40㎡、土塀付","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0220","desc":"仏殿南方の一段高い敷地に北面して建つ。方三間規模の宝形造桟瓦葺で、背面に壇を付設する。堂内は瓦敷、棹縁天井の一室とし、背面に接して中央に須弥壇、両脇に祖師壇を構える。須弥壇上部は粽付円柱で、禅宗様三手先詰組とし、桟唐戸をたてる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007681"},{"id":"00007683","register_sub_id":"101","register_pk":"108665","name":"寶福寺開山堂石垣及び土塀","kana":"ほうふくじかいざんどういしがきおよびどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1973-1他","lat":34.69064459,"lng":133.73438721,"geo_status":"db","era":"文化3","year":1806,"year_source":"db","year_min":1806,"year_max":1806,"year_label":null,"structure":"石垣 石造、総延長24m、塀 土塀、瓦葺、総延長19m、石段付","structure_material":"石垣 石造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0222","desc":"開山堂敷地の北側に設けられる。表門正面に石段を築き、その両脇から矩折れに東西に延びる。石垣は総延長２４ｍ高さ１．６ｍで割石乱積とし、隅を算木積とする。土塀は総延長１９ｍ高さ１．７ｍの築地塀で中塗仕上げとする。開山堂の格式ある佇まいを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007683"},{"id":"00007682","register_sub_id":"101","register_pk":"108664","name":"寶福寺開山堂表門","kana":"ほうふくじかいざんどうおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1973-1","lat":34.69061298,"lng":133.7344843,"geo_status":"db","era":"文化3／昭和中期改修","year":1806,"year_source":"db","year_min":1806,"year_max":1806,"year_label":null,"structure":"木造、瓦葺、間口2.1m、左右袖塀付","structure_material":"木造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0221","desc":"開山堂の正面に建つ四脚門。切妻造本瓦葺で、両側面に袖塀を設け、西に潜りを穿つ。円柱で、三斗組。妻は虹梁大瓶束とし、一軒疎垂木。本柱と控柱は腰長押や頭貫、台輪で固め、長押上に菱文様を彫った板壁を嵌める。扉は桟唐戸両開。手堅い意匠になる四脚門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007682"},{"id":"00007673","register_sub_id":"101","register_pk":"108655","name":"寶福寺経蔵","kana":"ほうふくじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69100641,"lng":133.73393856,"geo_status":"db","era":"宝暦14／明治16改修","year":1764,"year_source":"db","year_min":1764,"year_max":1764,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積17㎡","structure_material":"土蔵造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0212","desc":"仏殿の西北、一段高い位置に東面して建つ。宝形造本瓦葺で、唐破風造一間向拝を付ける。方二間規模の土蔵造で、切石積基礎上に建ち、白漆喰仕上げとする。軒は出桁造とし、側面に花頭形の窓を穿つ。内部は板張の一室。向拝の蟇股など、仏寺らしい意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007673"},{"id":"00007589","register_sub_id":"101","register_pk":"108571","name":"寶福寺庫裏","kana":"ほうふくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69138132,"lng":133.73435996,"geo_status":"db","era":"江戸中期／明治16・昭和60頃改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積432㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0206","desc":"玄関及び食堂の東に南面して建つ。桁行２６ｍ梁間１２ｍ規模の木造２階建。切妻造妻入本瓦葺で、正面は柱や梁、貫などを現し、中央の入口に起りのある小屋根を出す。入口土間奥に広間、両脇に知客寮や典座などを配する。近世禅院における庫裏の形態をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007589"},{"id":"00007588","register_sub_id":"101","register_pk":"108570","name":"寶福寺玄関及び食堂","kana":"ほうふくじげんかんおよびじきどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69132368,"lng":133.734192,"geo_status":"db","era":"江戸後期／明治中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0205","desc":"方丈の東に南面して建つ。桁行１４ｍ梁間８．２ｍ規模。屋根は南面を軒唐破風付の入母屋造とし、本瓦葺。正面に式台を構え、その奥を玄関とし、両脇に副司寮と殿司寮、さらに廊下を介して奥に食堂を配する。山陽における臨済宗の拠点寺院の格式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007588"},{"id":"00007678","register_sub_id":"101","register_pk":"108660","name":"寶福寺山門","kana":"ほうふくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69096168,"lng":133.73472136,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口4.4m","structure_material":"木造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0217","desc":"仏殿の前方に東面して建つ一間一戸楼門。入母屋造桟瓦葺。上層は桁行三間梁間二間で、横板壁とし、正面中央間に両開板戸をたてる。木鼻付出組で、二軒繁垂木とする。下層は出三斗で格天井を張り、両開桟唐戸を吊る。簡明な意匠で、禅林の正面を厳かに画する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007678"},{"id":"00007679","register_sub_id":"101","register_pk":"108661","name":"寶福寺山門石垣及び土塀","kana":"ほうふくじさんもんいしがきおよびどべい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.6909336,"lng":133.73474763,"geo_status":"db","era":"江戸後期／昭和前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石垣 石造、総延長52m、塀 土塀、瓦葺、総延長40m、石段付","structure_material":"石垣 石造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0218","desc":"境内の東方、山門正面に石段を設け、その南北に石垣で一段高い敷地を形成し、上部に土塀を造る。北側延長２９ｍ南側延長２３ｍ、高さ２．５ｍ規模の、安山岩の切石亀甲積。土塀は総延長４０ｍで白漆喰仕上げ、瓦葺とする。山門とともに伽藍正面の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007679"},{"id":"00007675","register_sub_id":"101","register_pk":"108657","name":"寶福寺書院","kana":"ほうふくじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.6915683,"lng":133.73403319,"geo_status":"db","era":"明治中期／昭和33改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0214","desc":"方丈の北背面から渡廊下を介して繋がる。東西棟の入母屋造桟瓦葺で、瓦葺下屋庇を付ける。西に四畳半、東に六畳を配し、北に一間幅の畳敷、南から西面に榑縁をまわす。四畳半には西面にトコと付書院を並べ、落掛を自然木とし、趣のある居室とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007675"},{"id":"00007674","register_sub_id":"101","register_pk":"108656","name":"寶福寺鐘楼","kana":"ほうふくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69118726,"lng":133.7344464,"geo_status":"db","era":"文政元","year":1818,"year_source":"db","year_min":1818,"year_max":1818,"year_label":null,"structure":"木造、瓦葺、面積7.8㎡","structure_material":"木造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0213","desc":"方丈の東南方に位置する方一間吹放ちの鐘楼。切石積基礎上に建ち、屋根は南北棟の入母屋造本瓦葺。四方転びの方柱で、腰貫や内法貫、頭貫、台輪で固め、三斗組とする。中備に蟇股を置き、軒は一軒疎垂木。妻を小さく、勾配を緩くして、穏やかな佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007674"},{"id":"00007672","register_sub_id":"101","register_pk":"108654","name":"寶福寺千尺井","kana":"ほうふくじせんじゃくせい","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69074358,"lng":133.73407,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"石造、面積2.4㎡","structure_material":"石造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0211","desc":"仏殿の西南に位置する。東西１．５ｍ南北１．６ｍ規模で、０．１５ｍ厚の花崗岩切石を枠石とし、４枚を相欠にして井桁に組む。井戸孔内は丸石積。仏殿での行事などに使われる井戸で、境内で最も古いと伝わる。規模が大きいながら、枠石を薄くし品よく仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007672"},{"id":"00007676","register_sub_id":"101","register_pk":"108658","name":"寶福寺禅堂","kana":"ほうふくじぜんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.691444,"lng":133.73373279,"geo_status":"db","era":"文化11／明治39・昭和40頃改修","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積95㎡、井戸付","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0215","desc":"方丈西北に南面して建ち、北に井戸を付設。桁行１１ｍ梁間８．１ｍ、入母屋造妻入桟瓦葺で、正面に向拝を付ける。正面は中央に引違腰障子戸をたて、両脇間に花頭窓を穿つ。内部は左右に単を設け、中央２間幅を四半瓦敷とし、厨子を置く。禅堂の形態をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007676"},{"id":"00007592","register_sub_id":"101","register_pk":"108574","name":"寶福寺典座井戸","kana":"ほうふくじてんぞいど","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69129719,"lng":133.7344187,"geo_status":"db","era":"文化11","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"石造、面積1.5㎡、上屋付","structure_material":"石造","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0209","desc":"庫裏典座の南方に位置する。厚さ１３㎝の花崗岩切石を井桁に組み枠石とする。方１．２ｍ高さ０．４９ｍ。その周囲に桁行２．１ｍ梁間１．８ｍ規模、切妻造本瓦葺の上屋を設ける。東・北面を開放し、他面に腰壁を設ける。近世禅院における庫裏に関連施設の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007592"},{"id":"00007680","register_sub_id":"101","register_pk":"108662","name":"寶福寺獨木橋","kana":"ほうふくじどくぼっきょ","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.690987,"lng":133.735016,"geo_status":"db","era":"文政11","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"石造、橋長2.9m","structure_material":"石造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0219","desc":"山門石段の東方に位置する。長さ２．９ｍ幅３．６ｍの石造桁橋。上面をアーチ状に造る石桁３本を架し、長さ１．９ｍの板石を２列に並べ、欄干石を置き、親柱石を建てる。材は花崗岩。穏やかな反りをもつ石橋で、欄干に鎬を付けるなど丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007680"},{"id":"00007591","register_sub_id":"101","register_pk":"108573","name":"寶福寺中井戸","kana":"ほうふくじなかいど","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.691452,"lng":133.734146,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、面積1.2㎡、上屋付","structure_material":"石造","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0208","desc":"食堂北側の濡縁に接する。厚さ１７㎝の花崗岩切石を井桁に組み枠石とする。方１．１ｍ高さ０．４２ｍ。食堂などで使われる。井戸の周囲に桁行１．７ｍ梁間１．１ｍ規模、切妻造桟瓦葺の上屋を設ける。四隅に方柱を建て、貫等で固め、梁に釣瓶を下げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007591"},{"id":"00007671","register_sub_id":"101","register_pk":"108653","name":"寶福寺仏殿","kana":"ほうふくじぶつでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69087723,"lng":133.7342507,"geo_status":"db","era":"享保20／文政4・明治16改修","year":1735,"year_source":"db","year_min":1735,"year_max":1735,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0210","desc":"山内南寄りに東面して建つ。桁行５間梁間５間で、一重もこし付風に造る。入母屋造本瓦葺、妻虹梁大瓶束で、正・側面は中央間を桟唐戸、両脇間を円窓とする。壁白漆喰仕上げで、上部に弓形欄間を設ける。身舎は出組詰組で、二軒扇垂木。江戸中期禅宗仏殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007671"},{"id":"00007587","register_sub_id":"101","register_pk":"108569","name":"寶福寺方丈","kana":"ほうふくじほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69133874,"lng":133.73392498,"geo_status":"db","era":"江戸末期／昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積486㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0204","desc":"境内地の北寄りに南面して建ち、背面に東司を付ける。入母屋造本瓦葺で、妻面は出組など組物で四重に梁を重ねる。桁行２４ｍ梁間１８ｍ規模。六間取を基本に正側面に広縁をまわし、裏方丈や茶頭寮などを付設する。地方における大規模な方丈建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007587"},{"id":"00007677","register_sub_id":"101","register_pk":"108659","name":"寶福寺方丈土塀","kana":"ほうふくじほうじょうどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69113314,"lng":133.73376354,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長65m","structure_material":"土塀","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0216","desc":"方丈前庭の南辺西寄りから西辺を画し、さらに禅堂前方で西に延びる総延長６５ｍの土塀。基礎を石垣状につくり、敷地の高低差を調整する。白漆喰仕上げで、方丈前が高さ１．４ｍで桟瓦葺、禅堂前と西辺土塀は高さ１．５ｍで、照り起りのある伏間瓦で葺く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007677"},{"id":"00007590","register_sub_id":"101","register_pk":"108572","name":"寶福寺宝蔵","kana":"ほうふくじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.691635,"lng":133.73418406,"geo_status":"db","era":"寛政5","year":1793,"year_source":"db","year_min":1793,"year_max":1793,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0207","desc":"庫裏の後方に東西棟で建つ。桁行７．９ｍ梁間４．９ｍの土蔵造２階建、切妻造桟瓦葺。外壁は漆喰壁、腰を海鼠壁とし、四隅では海鼠壁を鉢巻まで立ち上げ、妻上部や平側の窓下端などに海鼠壁と水切り瓦をまわす。極めて丁寧に造られ、意匠的に見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007590"},{"id":"00007570","register_sub_id":"101","register_pk":"108552","name":"妙教寺朝日天王社","kana":"みょうきょうじあさひてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.7103136,"lng":133.834,"geo_status":"db","era":"明治42／昭和54移築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.8㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0187","desc":"本殿の西北に南面して建つ一間社。千鳥破風付入母屋造檜皮葺で、正面に軒唐破風付一間向拝を設ける。支輪付四手先で二、三手目にも通肘木を架し、隅方向に尾垂木を付ける。二軒繁垂木。絵様などの彫りは太く、象や唐獅子、雲など彫刻は独特の雰囲気をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007570"},{"id":"00007569","register_sub_id":"101","register_pk":"108551","name":"妙教寺荒熊天王社","kana":"みょうきょうじあらくまてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710262,"lng":133.834061,"geo_status":"db","era":"大正8／昭和54移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積2.1㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0186","desc":"本殿の後方に位置する一間社。千鳥破風付入母屋造檜皮葺で、正面に軒唐破風付一間向拝を設ける。切目縁を四周にまわし、腰組は出組。龍彫刻の尾垂木付三手先斗栱で、各所を彫物で飾り、扉も装飾的な格子戸とする。末社群中で最も装飾的な社殿のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007569"},{"id":"00007567","register_sub_id":"101","register_pk":"108549","name":"妙教寺縁引天王社","kana":"みょうきょうじえんびきてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71011273,"lng":133.834183,"geo_status":"db","era":"明治21／昭和54移築","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0184","desc":"妙正天王社に北隣に位置する一間社流造檜皮葺。切石基礎上に石造亀腹を造り、土台を置く。身舍は円柱で、切目長押や内法長押、頭貫、台輪で固め、三斗組、一軒繁垂木とする。明治期に遡る末社のひとつ。小規模で、彫物装飾がなく、簡明な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007567"},{"id":"00007573","register_sub_id":"101","register_pk":"108555","name":"妙教寺大乗天王社","kana":"みょうきょうじおおのりてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710251,"lng":133.833817,"geo_status":"db","era":"大正6／昭和54移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0190","desc":"羽弥御崎天王社の南に位置する一間社流造檜皮葺。正側面に擬宝珠高欄付切目縁をまわす。縁及び浜縁に縁束を建てず、二手先の挿肘木で持ち出す。身舍は円柱で、三斗組とし、向拝は几帳面取方柱で皿斗付三斗組。同時期の妙正天王社と同じ規模・形式になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007573"},{"id":"00007558","register_sub_id":"101","register_pk":"108540","name":"妙教寺御水舎","kana":"みょうきょうじおみずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.708652,"lng":133.833191,"geo_status":"db","era":"昭和29／昭和54・平成18移築","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、面積12㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0175","desc":"本堂の西方に南北棟で建つ。桁行４．８ｍ梁間２．５ｍ、切妻造桟瓦葺、吹放ちとし、中央に水盤を置く。柱は方柱で脇柱を建て、柱上に三斗を組む。中備に蟇股を入れ、軒は一軒疎垂木。妻は豕叉首組とする。絵様や木鼻などに近代的な意匠をよく表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007558"},{"id":"00007574","register_sub_id":"101","register_pk":"108556","name":"妙教寺御厩舎","kana":"みょうきょうじおんきゅうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71023173,"lng":133.83377747,"geo_status":"db","era":"昭和前期／昭和54移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積5.2㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0191","desc":"大乗天王社の南に東面して建つ。桁行２．９ｍ梁間１．８ｍの切妻造妻入本瓦葺。土台上に方柱を建て、柱上に舟肘木を置く。一軒疎垂木。正面に両開戸を設け、壁を腰板張の漆喰壁とし、前寄りに窓を開ける。内部は土間床で神馬像を安置。小規模な神厩舎の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007574"},{"id":"00007555","register_sub_id":"101","register_pk":"108537","name":"妙教寺寒松軒","kana":"みょうきょうじかんしょうけん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70911796,"lng":133.8333851,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積77㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0172","desc":"庫裏の北に接し、西側は庭に面する。桁行８．９ｍ梁間９．０ｍの木造２階建、入母屋造桟瓦葺。１階は田の字型に４室を配し、主室にはトコを構える。１階はガラス戸をたて開放的にし、２階は白漆喰で塗り込め、格狭間風の窓を開ける。前面の庭園を意識した建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007555"},{"id":"00007554","register_sub_id":"101","register_pk":"108536","name":"妙教寺客殿及び庫裏","kana":"みょうきょうじきゃくでんおよびくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70896755,"lng":133.83345093,"geo_status":"db","era":"大正5／平成18改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積562㎡、渡廊下付","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0171","desc":"本堂の西北に位置する。東西棟入母屋造の客殿の東端に、南北棟切妻造の庫裏が付く。庫裏正面は柱や梁、蟇股などの架構を現し、その西方に唐破風造の大玄関を構える。屋根は本瓦葺。客殿は田の字型に４室を配し、座敷飾りを備える。重厚で風格ある構えをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007554"},{"id":"00007563","register_sub_id":"101","register_pk":"108545","name":"妙教寺五社天王社","kana":"みょうきょうじごしゃてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70999927,"lng":133.83403427,"geo_status":"db","era":"明治29／昭和54移築","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積5.0㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0180","desc":"霊応殿を中心にして七十七末社が配されるが、その中で唯一の五間社。本殿東側の南端に位置する。流造檜皮葺、高い切石積基壇上に建つ。出組を詰組とし、組物間に蟇股を入れる。妻は虹梁大瓶束で外に持ち出す。効果的に彫刻を用い、落ち着きのある意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007563"},{"id":"00007564","register_sub_id":"101","register_pk":"108546","name":"妙教寺三光天王社","kana":"みょうきょうじさんこうてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710049,"lng":133.834106,"geo_status":"db","era":"昭和2／昭和54移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.5㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0181","desc":"本殿東側末社群の中央に建つ。正面一間側背面二間、千鳥破風付入母屋造檜皮葺で、正面に軒唐破風付一間向拝。身舎を出組、腰組を四手先とし、通肘木上に斗を並べる。水引虹梁や繋虹梁を龍彫刻とする他、中備や方立、脇障子、腰板など華やかな彫物装飾で充たす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007564"},{"id":"00007559","register_sub_id":"101","register_pk":"108541","name":"妙教寺山門","kana":"みょうきょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70881448,"lng":133.83318444,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造、瓦葺、間口3.3m、左右袖塀付","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0176","desc":"本堂の正面西方に、西面して建つ。規模の大きな一間一戸薬医門、切妻造本瓦葺。本柱上に冠木を架し、男梁を渡し、三斗を組み、軒桁や妻虹梁大瓶束を持ち上げる。軒は二軒半繁垂木。彫物は良質で蟇股や笈形などに限定的に用いられ、構造的に見応えがある山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007559"},{"id":"00007583","register_sub_id":"101","register_pk":"108565","name":"妙教寺鐘楼","kana":"みょうきょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70958456,"lng":133.83327472,"geo_status":"db","era":"文久2／昭和33・昭和54移築","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造、瓦葺、面積9.3㎡","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0200","desc":"霊応殿社殿群の西南方に位置する。亀甲積基壇上に建つ、桁行３．０ｍ梁間３．０ｍの四方吹放ちの鐘楼。入母屋造本瓦葺。方柱を腰貫と内法貫、頭貫、台輪で固め、三斗組とし、中備に蟇股を置く。標準的な方一間鐘楼で、大棟棟瓦や鯱など飾瓦が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007583"},{"id":"00007575","register_sub_id":"101","register_pk":"108557","name":"妙教寺末廣天王社","kana":"みょうきょうじすえひろてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71015927,"lng":133.83371,"geo_status":"db","era":"明治12／昭和54移築","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積0.65㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0192","desc":"経王殿の西側に東面して建つ。小規模な一間社で、流造檜皮葺。切石積基壇上に土台を置き、柱を建てる。身舍は円柱で、切目長押や内法長押、頭貫、薄い台輪で固める。板支輪付出組とし、妻を一段持ち出す。彫刻装飾は限定的であり、質実な意匠にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007575"},{"id":"00007584","register_sub_id":"101","register_pk":"108566","name":"妙教寺清正公堂","kana":"みょうきょうじせいしょうこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.707542,"lng":133.83501992,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.5㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0201","desc":"本堂や霊応殿などから離れた、境内の東南端に所在する。小高い位置に南面して建つ一間社で、入母屋造銅板葺。正面に一間向拝を付ける。龍彫刻とする尾垂木付三手先詰組で、縁及び浜縁の腰組を四手先斗栱とするなど、軒や縁まわりが斗栱で賑やかに飾られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007584"},{"id":"00007556","register_sub_id":"101","register_pk":"108538","name":"妙教寺太鼓楼及び渡廊下","kana":"みょうきょうじたいころうおよびわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.709145,"lng":133.833282,"geo_status":"db","era":"明治後期／大正前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"太鼓楼 木造2階建、瓦葺、建築面積6㎡、渡廊下 木造、瓦葺、面積58㎡","structure_material":"太鼓楼 木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0173","desc":"客殿北面西端から北に延びる廊下で、北端に階段室を兼ねる太鼓楼を設ける。太鼓楼は建ちの高い方２．４ｍの建築で、宝形造本瓦葺。渡り廊下は切妻造桟瓦葺で、途中に寄棟造の方３．３ｍ板敷を設ける。客殿北の庭を画し、庭園景観を構成する一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007556"},{"id":"00007585","register_sub_id":"101","register_pk":"108567","name":"妙教寺仁王門","kana":"みょうきょうじにおうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和中","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.708729,"lng":133.832916,"geo_status":"db","era":"昭和32","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造、面積97㎡","structure_material":"鉄筋コンクリート造","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0202","desc":"参道正面に建つ。花崗岩切石貼のＲＣ造。中央に方４．２ｍ、四隅に方３．９ｍの矩形平面を張り出す独特の構成になり、各々にドーム状の屋根を載せ、相輪を立てる。中央棟をアーチ形に開け通路とし、他には仁王像等を安置。伝統的な社頭景観において異彩を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007585"},{"id":"00007571","register_sub_id":"101","register_pk":"108553","name":"妙教寺信受・照両天王社","kana":"みょうきょうじのぶ・あきりょうてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71028867,"lng":133.83387267,"geo_status":"db","era":"昭和6／昭和54移築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積0.62㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0188","desc":"本殿の西側に東面する小規模な一間社で、切石積基壇上に建つ。千鳥破風付入母屋造檜皮葺で、出組を詰組とし、二軒繁垂木。正面の一間向拝に大きく軒唐破風を付け、水引虹梁を龍、兎毛通を鳳凰の彫物として装飾するが、建物規模に対してやや大振りな印象である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007571"},{"id":"00007572","register_sub_id":"101","register_pk":"108554","name":"妙教寺羽弥御崎天王社","kana":"みょうきょうじはやみさきてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710266,"lng":133.833847,"geo_status":"db","era":"大正10／昭和54移築","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積2.2㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0189","desc":"信受・照両天王社の南に位置し、末社群中で最も規模の大きい一間社。千鳥破風付入母屋造檜皮葺で、軒唐破風付一間向拝を設ける。龍と雲の二重尾垂木を付ける三手先詰組で、向拝ほかを多くの彫刻で充たす。装飾的、様式的に密度が濃い社殿建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007572"},{"id":"00007568","register_sub_id":"101","register_pk":"108550","name":"妙教寺日車天王社","kana":"みょうきょうじひぐるまてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710209,"lng":133.83412633,"geo_status":"db","era":"明治41／昭和54移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積2.0㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0185","desc":"本殿東北に建つ一間社。千鳥破風付入母屋造檜皮葺で、正面に軒唐破風付一間向拝を設ける。尾垂木を龍彫刻とする二手先詰組で、組物間にも彫物を飾る。繋虹梁を龍の丸彫、水引虹梁の絵様を浮彫とする向拝まわりや、唐獅子の脇障子など、豊かな彫物装飾をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007568"},{"id":"00007576","register_sub_id":"101","register_pk":"108558","name":"妙教寺秀義天王社","kana":"みょうきょうじひでよしてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710136,"lng":133.833679,"geo_status":"db","era":"明治3／昭和54移築","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積0.47㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0193","desc":"末廣天王社の南に位置する。一間社流造檜皮葺。切石基壇上に石造の亀腹を置き、土台建とする。身舍は円柱で、支輪付出組とし、中備に彫物を入れる。妻は虹梁大瓶束で、前に持ち出す。要所に彫物装飾を配しており、小規模ながら丁寧に造り込まれた社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007576"},{"id":"00007557","register_sub_id":"101","register_pk":"108539","name":"妙教寺宝光閣","kana":"みょうきょうじほうこうかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70917176,"lng":133.83319648,"geo_status":"db","era":"明治42／昭和54改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋地下1階建、瓦葺及び銅板葺、建築面積97㎡","structure_material":"木造平屋地下1階建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0174","desc":"太鼓楼の西南に建つ。入母屋造で軒先銅板葺の桟瓦葺とし、千鳥破風を付ける。舟肘木で一軒疎垂木。腰板張の白漆喰壁で、南面に花頭窓を開ける。後方は道に張り出し、煉瓦造の基礎を高く建ち上げ、アーチを設ける。高い煉瓦積基礎と伝統的木造が独特の外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007557"},{"id":"00007553","register_sub_id":"101","register_pk":"108535","name":"妙教寺本堂","kana":"みょうきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70869389,"lng":133.83356298,"geo_status":"db","era":"明治15／平成18移築","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積202㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0170","desc":"境内地の東南に西面して建つ、入母屋造本瓦葺の二重仏堂。正面三間側面六間で、背面に一間通りの位牌堂を付設し、正側面に縁をまわす。内部は凹型外陣とその奥の内陣からなり、背面に接して須弥壇を構える。禅宗仏殿の形態を受け継ぐ日蓮宗仏堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007553"},{"id":"00007566","register_sub_id":"101","register_pk":"108548","name":"妙教寺妙正天王社","kana":"みょうきょうじよしまさてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71009507,"lng":133.834152,"geo_status":"db","era":"大正6／昭和54移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0183","desc":"夜守天王社の北に位置する一間社流造檜皮葺。正側面に擬宝珠高欄付切目縁をまわす。正面に浜床と浜縁を付け、身舎円柱を切目長押と内法長押、頭貫、台輪で固めるなど、境内の多くの末社と共通する構造形式になる。三斗組、一軒繁垂木。装飾的要素を抑えた社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007566"},{"id":"00007565","register_sub_id":"101","register_pk":"108547","name":"妙教寺夜守天王社","kana":"みょうきょうじよもりてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71006692,"lng":133.83412931,"geo_status":"db","era":"昭和前期／昭和54移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0182","desc":"三光天王社の北に建つ一間社。入母屋造妻入檜皮葺で、一間向拝を付ける。浜床と浜縁を付け、身舍は四周に組高欄付縁をまわす。身舍は円柱で、切目長押や内法長押、頭貫、台輪で固め、出組を詰組とする。二軒繁垂木。向拝木鼻は複雑な絵様を彫り残す籠彫とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007565"},{"id":"00007560","register_sub_id":"101","register_pk":"108542","name":"妙教寺霊応殿経王殿","kana":"みょうきょうじれいおうでんきょうおうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710079,"lng":133.833832,"geo_status":"db","era":"明治30／昭和54移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積59㎡、渡廊下及び小部屋付","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0177","desc":"境内の東北奥に位置する。本殿正面に建つ切妻造妻入檜皮葺で、正面は落棟で拝殿と繋ぎ、背面に唐破風造の突出部を付ける。内部は畳敷で、折上小組格天井を張り、正側面に高欄付切目縁をまわす。円柱で支輪付出組、二軒繁垂木。細部まで丁寧な仕上げになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007560"},{"id":"00007562","register_sub_id":"101","register_pk":"108544","name":"妙教寺霊応殿前殿","kana":"みょうきょうじれいおうでんぜんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.709953,"lng":133.8336854,"geo_status":"db","era":"明治19／昭和54移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0179","desc":"拝殿正面に繋がる桁行四間梁間一間の細長い建物。唐破風造妻入檜皮葺。方柱で、大斗肘木とし、中備に蟇股形の彫刻を飾る。梁行に虹梁を架け、菊水などを彫る笈形付大瓶束を置く。石敷で、化粧屋根裏天井。経王殿や拝殿と一体となり、荘厳な礼拝空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007562"},{"id":"00007561","register_sub_id":"101","register_pk":"108543","name":"妙教寺霊応殿拝殿","kana":"みょうきょうじれいおうでんはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71000893,"lng":133.83375287,"geo_status":"db","era":"明治19／昭和54移築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0178","desc":"経王殿の正面に建つ。入母屋造檜皮葺。桁行三間梁間三間で、周囲を吹き放つ。正背面中央間を広くとり、虹梁を架す。布基礎石をまわし、その上に礎盤を置き円柱を建てる。平三斗で、二軒繁垂木。内部は格天井で、基礎天端にあわせて低い板床を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007561"},{"id":"00007577","register_sub_id":"101","register_pk":"108559","name":"妙教寺六社天王社一富天王社","kana":"みょうきょうじろくしゃてんのうしゃいちとみてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.7094665,"lng":133.83353811,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0194","desc":"霊応殿の社殿群から少し離れた南方の位置に、六社天王社と総称される６棟の末社群が配され、その北端に西面して建つ。一間社流造檜皮葺。組物は三斗組で、中備を略す。軒は繁垂木で、正面のみ二軒とする。妻は虹梁豕叉首組。抑制の利いた落ち着いた意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007577"},{"id":"00007580","register_sub_id":"101","register_pk":"108562","name":"妙教寺六社天王社白糸天王社","kana":"みょうきょうじろくしゃてんのうしゃしらいとてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70939425,"lng":133.83351836,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0197","desc":"大元鬼天王社の南に位置する。一間社流造檜皮葺。切石基壇上に石造亀腹を置き、土台建とする。身舎は円柱で、切目長押や内法長押、頭貫、薄い台輪で固める。三斗組で、妻は虹梁豕叉首組。一富天王社や夜守天王社と細部の特徴も含めて同じ規模・形式になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007580"},{"id":"00007579","register_sub_id":"101","register_pk":"108561","name":"妙教寺六社天王社大元鬼天王社","kana":"みょうきょうじろくしゃてんのうしゃだいげんきてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70941914,"lng":133.83352515,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、檜皮葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0196","desc":"夜守天王社の南に位置する。切石基壇上に石造亀腹を置き、土台建とする一間社流造檜皮葺。身舍は円柱で、切目長押や内法長押、頭貫、薄い台輪で固める。柱上三斗組。妻を梁上に束立とし、正背面とも一軒繁垂木、浜縁を挿肘木で支持し、繋虹梁がなく手挟とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007579"},{"id":"00007582","register_sub_id":"101","register_pk":"108564","name":"妙教寺六社天王社福崎天王社","kana":"みょうきょうじろくしゃてんのうしゃふくさきてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70935702,"lng":133.83350549,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、檜皮葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0199","desc":"六社天王社のうち最も南に建つ一間社流造檜皮葺。切石基壇上に石造亀腹を置き、土台建。正面も一軒とし、向拝に手挟を用いるなど、大元鬼天王社に近い仕様になる。明治中期に建立された、ほぼ同じ規模・形式の社殿６棟が整然と並び建ち、厳粛な空間をつくり出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007582"},{"id":"00007581","register_sub_id":"101","register_pk":"108563","name":"妙教寺六社天王社福恵天王社","kana":"みょうきょうじろくしゃてんのうしゃふくよしてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70937791,"lng":133.83351249,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、檜皮葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0198","desc":"白糸天王社の南に建つ一間社流造檜皮葺。切石基壇上に石造亀腹を置き、土台建。円柱を切目長押や内法長押、頭貫、薄い台輪で固め、三斗組とする。妻は虹梁上に束立で、正面のみ二軒繁垂木とし、繋虹梁を略し、手挟とする。手挟や虹梁には若葉風絵様を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007581"},{"id":"00007578","register_sub_id":"101","register_pk":"108560","name":"妙教寺六社天王社夜守天王社","kana":"みょうきょうじろくしゃてんのうしゃよもりてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70944283,"lng":133.83353111,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0195","desc":"一富天王社の南に位置する。一間社流造檜皮葺。切石基壇上に石造の亀腹を置き、土台建とする。身舍は円柱で、切目長押や内法長押、頭貫、薄い台輪で固める。柱上三斗組、正面のみ二軒繁垂木で、妻は虹梁豕叉首組。縁を二手先の挿肘木、浜縁を持送りで支持する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007578"},{"id":"00015089","register_sub_id":"101","register_pk":"529367","name":"由加神社大鳥居","kana":"ゆがじんじゃおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島由加字瑜伽2852","lat":34.50561389,"lng":133.85106111,"geo_status":"db","era":"明治27年","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"炻器製、間口3.2m","structure_material":"炻器製","registered":"2024.08.15(令和6.08.15)","register_no":"33 - 0369","desc":"境内南西に位置し、西面して建つ大鳥居。柱間約三・二メートル、高さ約四・七メートル。備前焼の部材を組み上げた春日鳥居で、柱と貫の交差部や島木と笠木の一部などに一体焼成部材を用いる。高度な技術で製作した大規模備前焼作品で地域の象徴的存在の鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015089"},{"id":"00015088","register_sub_id":"101","register_pk":"529366","name":"由加神社三宝荒神社本殿","kana":"ゆがじんじゃさんぽうこうじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市児島由加字瑜伽2852","lat":34.50608333,"lng":133.85105,"geo_status":"db","era":"江戸後期／平成9年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"33 - 0368","desc":"本殿東隣に南面して建つ方一間、正面入母屋造、背面切妻造、妻入銅板葺。正面に１間向拝を付し、三方に擬宝珠高欄付の縁を廻す。身舎組物は連三斗とし、軒は二軒繁垂木、中備は蟇股。板状の頭貫木鼻など古式なつくりの本殿で、境内の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015088"},{"id":"00015087","register_sub_id":"101","register_pk":"529365","name":"由加神社拝殿及び幣殿","kana":"ゆがじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市児島由加字瑜伽2852","lat":34.50591667,"lng":133.85102778,"geo_status":"db","era":"安永6年（1777）／天保9年（1838）改修","year":1777,"year_source":"db","year_min":1777,"year_max":1777,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積142㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"33 - 0367","desc":"倉敷市街南東の瑜加山に位置する神社の拝殿及び幣殿。拝殿は南面して建つ入母屋造平入で正面に３間向拝を設け千鳥破風を付し、前方に向唐破風造向拝を突出する。背面は切妻造銅板葺の幣殿を延ばす。錺金具や彫刻など装飾濃密な向拝を付し独特な形式の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015087"},{"id":"00006576","register_sub_id":"101","register_pk":"107559","name":"龍乗院石段及び石垣","kana":"りゅうじょういんいしだんおよびいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県玉野市東田井地1326","lat":34.55650145,"lng":133.99594039,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石段 石造8段、幅9.0m、石垣 石造、総延長37m","structure_material":"石段 石造8段","registered":"2007.07.31(平成19.07.31)","register_no":"33 － 0158","desc":"鐘楼門下に幅約９ｍの石段８段が積まれ，その西側に石垣が設置され，寺域を画している。石垣の総延長は３７ｍで，高さを２．６ｍとする。石材加工や積み方はほぼ４区画に分けられ，積まれた時期が異なる。高台に築かれた寺院固有の景観を創り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006576"},{"id":"00006575","register_sub_id":"101","register_pk":"107558","name":"龍乗院鐘楼門","kana":"りゅうじょういんしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県玉野市東田井地1326","lat":34.55648,"lng":133.996109,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造及び鉄筋コンクリート造楼門、瓦葺、建築面積10㎡、左右袖塀付","structure_material":"木造及び鉄筋コンクリート造楼門","registered":"2007.07.31(平成19.07.31)","register_no":"33 － 0157","desc":"高台に位置する境内の石段上方に建つ。２層で，下層はＲＣ造とし，仕上げは腰部を花崗岩貼，その上を白色小口タイル貼のモダンな意匠とする。上層は伝統的な木造で，桁行２間，梁間１間半，入母屋造，本瓦葺とする。当地で類例を見ない混合構造の構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006575"},{"id":"00006307","register_sub_id":"101","register_pk":"107290","name":"龍乗院本堂","kana":"りゅうじょういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県玉野市東田井地1326","lat":34.5566894,"lng":133.99597837,"geo_status":"db","era":"文政2／昭和57改修","year":1819,"year_source":"db","year_min":1819,"year_max":1819,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積214㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"33 － 0156","desc":"寺山の麓の高台に位置する。桁行１３．６ｍ，梁間１２．２ｍ，木造平屋建，入母屋造，本瓦葺とする。６間取の方丈形式の平面をもち，東南に間口２間幅の式台玄関を付け，屋根を向唐破風造とする。妻飾り彫刻には狛犬，虎を用いるなど江戸後期らしい意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006307"},{"id":"00000097","register_sub_id":"101","register_pk":"101087","name":"厳島神社宝物館","kana":"いつくしまじんじゃほうもつかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県廿日市市宮島町118","lat":34.29477556,"lng":132.31862898,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積570㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"34 － 0005","desc":"鉄骨鉄筋コンクリート造で，大江新太郎の設計で清水組の施工と伝える。近代的な平面をもちながら伝統的な木造建築の形態や意匠を持つ建物を，近代的な材料で造っている点に特徴がある。当時の大江新太郎の作風をよく示した建物のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000097"},{"id":"00003598","register_sub_id":"101","register_pk":"104588","name":"耕三寺銀龍閣","kana":"こうさんじぎんりゅうかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30397476,"lng":133.0909089,"geo_status":"db","era":"昭和18","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0056","desc":"境内南東方の庭園池泉に張り出して建つ。八畳大の板間の三方に縁を廻らし，東側に床と小室を設ける。屋根は宝形造の銅板葺。板間は鏡天井として龍の絵を描き，軸部はすべて銀色とする。板間の障子に花頭窓を設ける点も特徴的で，特異な意匠の建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003598"},{"id":"00003589","register_sub_id":"101","register_pk":"104579","name":"耕三寺鼓楼","kana":"こうさんじころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30447393,"lng":133.08989324,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0047","desc":"羅漢堂西側背面に建ち，鐘楼と対をなす。鐘楼と同規模同形式で，細部装飾に至るまでほぼ完全に同一である。１階は四半敷の土間とし，上層に高欄を設けない縁を出し，二手先の組物に二軒繁垂木，入母屋造，本瓦葺とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003589"},{"id":"00003585","register_sub_id":"101","register_pk":"104575","name":"耕三寺山門","kana":"こうさんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30492321,"lng":133.09015693,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"鉄造、間口4.5m、左右袖塀付","structure_material":"鉄造","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0043","desc":"境内の北端にあって，伽藍中心軸上に位置する。柱四本を建て，中央に両開，両脇に片開の扉を吊り，両袖は瓦葺とする。柱，扉ともに鉄製で，白色を基調に随所に丹色を配し，扉には様々な絵柄の装飾を施す。街路に面して境内のランドマークとなる建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003585"},{"id":"00003593","register_sub_id":"101","register_pk":"104583","name":"耕三寺至心殿","kana":"こうさんじししんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.303974,"lng":133.089951,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0051","desc":"伽藍最上段西側に建ち，信楽殿と対をなす。法界寺阿弥陀堂を模したと伝えられ，５間四方の身舎に吹き放しの裳階を設け，屋根は宝形造銅板葺。組物は平三斗で，裳階の正面中央部のみ一段高く屋根を設ける。内部は１室とし，各種用途として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003593"},{"id":"00003588","register_sub_id":"101","register_pk":"104578","name":"耕三寺鐘楼","kana":"こうさんじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30452873,"lng":133.09048083,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0046","desc":"羅漢堂東側背面に建ち，鼓楼と同じ規模形式を持つ。桁行３間，梁間２間，入母屋造，本瓦葺で，白漆喰塗の袴腰を備える。新薬師寺鐘楼を模したもので，上部に高欄を持たない縁を張り出す。上層内部は中央部を吹き抜けとし，両側に床を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003588"},{"id":"00003594","register_sub_id":"101","register_pk":"104584","name":"耕三寺信楽殿","kana":"こうさんじしんぎょうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30402628,"lng":133.09055142,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0052","desc":"伽藍最上段の東側に建つ。至心殿とは対をなし，同規模同形式とするが，平面などに若干の違いがある。身舎柱は円柱，裳階柱は角柱で，講堂として用いられる身舎内部は１室とし，天井は折上小組格天井。四周外壁は蔀戸を見せるが，内側には壁が設けられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003594"},{"id":"00003592","register_sub_id":"101","register_pk":"104582","name":"耕三寺僧宝蔵","kana":"こうさんじそうほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.304272,"lng":133.090485,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0050","desc":"伽藍中段東側に建ち，同型同規模の法宝蔵と五重塔をはさんで対をなす。四天王寺金堂を参照しつつ大きく外観を変え，身舎は円柱に二手先，裳階は角柱に平三斗とし，内部は折上格天井の大空間とする。昭和前期における大規模木造寺院建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003592"},{"id":"00003596","register_sub_id":"101","register_pk":"104586","name":"耕三寺多宝塔","kana":"こうさんじたほうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30377986,"lng":133.08987097,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造多宝塔、銅板葺、建築面積25㎡","structure_material":"木造多宝塔","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0054","desc":"本堂西方に建つ。石山寺多宝塔を模しており，下層は方３間の周囲に縁を廻らし，上層は円形平面で四手先組物で二軒繁垂木の軒を支え，屋根は上層下層とも銅板葺とする。比較的原作に忠実であり，組物等に彩色を施した外観は壮麗である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003596"},{"id":"00003586","register_sub_id":"101","register_pk":"104576","name":"耕三寺中門","kana":"こうさんじちゅうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.3048091,"lng":133.09014972,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造、瓦葺、建築面積46㎡","structure_material":"木造","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0044","desc":"四間二戸の二重門で，入母屋造，本瓦葺。法隆寺の西院伽藍の中門を原型とするが，梁間は二間とし，各部比例も異なる。組物等の装飾はおおむね原型を踏襲しているが，飾金具，彩色などを多用して壮麗な外観としている。中心伽藍の北方を画す建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003586"},{"id":"00003597","register_sub_id":"101","register_pk":"104587","name":"耕三寺八角円堂","kana":"こうさんじはっかくえんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30384166,"lng":133.09066872,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0055","desc":"本堂を挟んで多宝塔と対置される。正八角形平面を持ち，屋根は宝形造，本瓦葺。法隆寺東院夢殿を模しているが，規模を縮小している。柱は八角柱で，組物は隅部出三斗，中備は平三斗，内部は板敷で，中央を鏡天井，周囲を格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003597"},{"id":"00003590","register_sub_id":"101","register_pk":"104580","name":"耕三寺仏宝蔵","kana":"こうさんじぶっぽうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.304546,"lng":133.09082952,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0048","desc":"一連の伽藍からはやや東寄りに建つ，桁行５間，梁間２間，平入，入母屋造，本瓦葺の宝蔵。内部は板敷で一室とする。耕三寺の建築の中では比較的簡素で，新薬師寺本堂を模したとされるが，規模，各柱間に長押，連子窓を設ける外観など大きく異なる点が多い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003590"},{"id":"00003591","register_sub_id":"101","register_pk":"104581","name":"耕三寺法宝蔵","kana":"こうさんじほうほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.304237,"lng":133.089951,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0049","desc":"伽藍中段に建つ宝物館で，僧宝蔵と対をなす。桁行４間，梁間３間の身舎四周に裳階を廻らす。屋根は入母屋造，本瓦の錣葺とする。四天王寺金堂を模したといわれるが，法宝蔵は妻入であり，屋根勾配，各部比例なども大きく異なる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003591"},{"id":"00003595","register_sub_id":"101","register_pk":"104585","name":"耕三寺本堂","kana":"こうさんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30375935,"lng":133.09028052,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積271㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0053","desc":"中堂，左右翼廊，尾廊からなる堂宇。いずれも本瓦葺とし，軸部，壁面，建具に至るまで極彩色を施し，飾金具を用いる。平等院鳳凰堂を模しているが，細部においては異なる点も多く，内部外部とも壮麗さを増しており，耕三寺の中核建築として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003595"},{"id":"00003587","register_sub_id":"101","register_pk":"104577","name":"耕三寺羅漢堂","kana":"こうさんじらかんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.3048338,"lng":133.09048393,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積346㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0045","desc":"中門の両側に続く回廊状の建築で，内部に羅漢像を安置する。左右とも桁行１７間，梁間１間の規模で，本瓦葺，切妻造とする。外側壁面を連子窓，内側を板扉とし，内部は板敷。小屋は虹梁，扠首組に化粧屋根裏とする。中心伽藍の中では最も初期の建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003587"},{"id":"00013340","register_sub_id":"101","register_pk":"366329","name":"榊󠄀森神社拝殿","kana":"さかきもりじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県安芸郡熊野町新宮八丁目601-2","lat":34.37038889,"lng":132.61719167,"geo_status":"db","era":"明治16年頃","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0282","desc":"本殿の南に渡殿及び幣殿を介し、南面して建つ。木造平屋建、正面入母屋造桟瓦葺で、背面の渡殿及び幣殿と一体に屋根を葺く。内部は一室で、出三斗に丸太梁を桁行に掛け現しとし、その上に天井を張る。入母屋造妻入の屋根は境内空間の象徴的な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013340"},{"id":"00013339","register_sub_id":"101","register_pk":"366328","name":"榊󠄀森神社本殿","kana":"さかきもりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸郡熊野町新宮八丁目601-2","lat":34.37049444,"lng":132.61726111,"geo_status":"db","era":"江戸末期／明治16年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0281","desc":"町の北部に位置し、石段を登った境内地の北西に南面して建つ。三間社流造銅板葺で、背面を除く三方に高欄付の縁を廻す。組物は出組で、中備を蟇股とする。妻飾りは二重虹梁蟇股で、棟木を大瓶束で受ける。庇の間の海老虹梁や欄間、板支輪などを彫刻で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013339"},{"id":"00013335","register_sub_id":"101","register_pk":"366324","name":"榊山八幡神社護国神社本殿","kana":"さかきやまはちまんじんじゃごこくじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"広島県","address":"広島県東広島市安芸津町三津字榊山5513","lat":34.31794444,"lng":132.81141389,"geo_status":"db","era":"昭和28年頃","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.3㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0277","desc":"拝殿前方の参道に東面して建つ、村内戦没者を祀る小社。正面一間、側面二間、流造銅板葺で、正側面に縁を廻して脇障子を建て、浜縁を設ける。身舎は粽付円柱で、台輪を廻して三斗を組み、正面桟唐戸や蟇股を菊花紋の彫刻で飾る。参道沿いの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013335"},{"id":"00013333","register_sub_id":"101","register_pk":"366322","name":"榊山八幡神社神門及び塀","kana":"さかきやまはちまんじんじゃしんもんおよびへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市安芸津町三津字榊山5513","lat":34.3184,"lng":132.81142778,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"神門 木造、瓦葺、間口1.8m 塀 木造、瓦葺、総延長78m","structure_material":"神門 木造","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0275","desc":"本殿の四周を囲繞する切妻造本瓦葺の神門と桟瓦葺の塀。神門は一間腕木門で、本柱後方に控柱を立て、上部を格子とした両開桟唐戸を吊る。塀は真壁漆喰塗で、腰上に竪格子を嵌める。簡素ながら上質なつくりで、森厳な本殿周りの景観を格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013333"},{"id":"00013336","register_sub_id":"101","register_pk":"366325","name":"榊山八幡神社随身門","kana":"さかきやまはちまんじんじゃずいじんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県東広島市安芸津町三津字榊山5513","lat":34.31762222,"lng":132.81154444,"geo_status":"db","era":"天明2年(1782)頃／昭和10年代改修","year":1782,"year_source":"db","year_min":1782,"year_max":1782,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0278","desc":"参道の中段に南面して建つ。三間一戸八脚門、入母屋造銅板葺で、組物は出三斗で二軒半繁垂木とする。広く取った中央間は門扉を設けず吹放ち、両脇間後方を格子戸と板壁で区画して随身像と狛犬を祀る。境内唯一の近世建築で、参道景観に風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013336"},{"id":"00013332","register_sub_id":"101","register_pk":"366321","name":"榊山八幡神社拝殿及び幣殿","kana":"さかきやまはちまんじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市安芸津町三津字榊山5513","lat":34.31833889,"lng":132.81144167,"geo_status":"db","era":"明治40年／昭和58年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0274","desc":"本殿正面石段下に南面して建つ。入母屋造銅板葺、軒唐破風付一間向拝付で背面に幣殿を張出す。拝殿は平三斗組、二軒繁垂木、中備は彫刻蟇股とし、正面一間通りを吹放し、四周に縁を廻す。幣殿は舟肘木、一軒繁垂木と簡素につくる。社頭景観を重厚に演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013332"},{"id":"00013331","register_sub_id":"101","register_pk":"366320","name":"榊山八幡神社本殿","kana":"さかきやまはちまんじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市安芸津町三津字榊山5513","lat":34.31849167,"lng":132.81144167,"geo_status":"db","era":"明治40年／昭和前期改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0273","desc":"海を臨む丘上にある神社。本殿は境内北奥の上段に南面して建つ。方三間、入母屋造銅板葺、正面千鳥破風、軒唐破風付一間向拝付。四周に縁を廻して浜縁を設ける。組物は出組、二軒繁垂木とし、板支輪や木鼻、蟇股などを彫刻で飾る。重厚なつくりの本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013331"},{"id":"00013334","register_sub_id":"101","register_pk":"366323","name":"榊山八幡神社松尾神社本殿","kana":"さかきやまはちまんじんじゃまつおじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市安芸津町三津字榊山5513","lat":34.31862778,"lng":132.81150278,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.5㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0276","desc":"酒造関係者により京都の松尾大社より勧請され、本殿北東に南面して建つ小社。一間社流造銅板葺で、正側面に縁を廻して脇障子を建て、浜縁を設ける。身舎は粽付円柱で、台輪を廻して三斗を組み、海老虹梁で庇と繋ぐ。地域の酒造業繁栄の歴史を物語る社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013334"},{"id":"00008777","register_sub_id":"101","register_pk":"149498","name":"照林坊御成の間","kana":"しょうりんぼうおなりのま","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80890542,"lng":132.84714642,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"converted","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0118","desc":"客殿の東南に廊下を介して続く。入母屋造桟瓦葺で、周囲に下屋をまわす。東西に3室を並べ、周囲に縁をまわし、南背面に浴室や便所を付設する。東端を主室とし、トコやトコ脇、付書院を構える。各室に棹縁天井を張り、砂壁として、落ち着きのある設えをなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008777"},{"id":"00008781","register_sub_id":"101","register_pk":"149502","name":"照林坊鐘撞堂","kana":"しょうりんぼうかねつきどう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80918661,"lng":132.84763899,"geo_status":"db","era":"江戸中期／延享元年(1744)・平成6年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、面積16㎡","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0122","desc":"本堂の東南に位置する。切石積基壇に建つ桁行1間梁間1間の吹放ち鐘楼。入母屋造桟瓦葺。礎盤に粽付円柱を内転びにたて、貫や台輪で固め、尾垂木付二手先斗栱を組む。柱間中央にも斗栱を置き、その間に蟇股を飾る。二軒繁垂木。近世建立になる良質な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008781"},{"id":"00008776","register_sub_id":"101","register_pk":"149497","name":"照林坊客殿","kana":"しょうりんぼうきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80903913,"lng":132.84700878,"geo_status":"db","era":"昭和9年／昭和61年改修","year":1934,"year_source":"converted","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0117","desc":"本堂の西南に位置する。入母屋造妻入本瓦葺、正面に唐破風造玄関を付け、周囲に下屋をまわす。内部は対面所と、座敷飾りを備える座敷に2分され、対面所は大トコを構える17畳半で、側面に鞘の間、前方に玄関の間を付ける。近代における真宗対面所の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008776"},{"id":"00008780","register_sub_id":"101","register_pk":"149501","name":"照林坊経蔵","kana":"しょうりんぼうきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県三次市三次町1280","lat":34.8094786,"lng":132.84752396,"geo_status":"db","era":"江戸中期／宝暦2年(1752)・明治45年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造平屋建、瓦葺、建築面積20㎡","structure_material":"土蔵造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0121","desc":"本堂の東北に南面して建つ。方3.8ｍの土蔵造、宝形造桟瓦葺で、1間向拝を付ける。鉢巻上に台輪を置き、出三斗組とし、中備に蟇股を飾る。軒は一軒繁垂木。内部は1室の板敷で、格天井を張る。見応えのある組物や蟇股、彫物などが各所に配される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008780"},{"id":"00008778","register_sub_id":"101","register_pk":"149499","name":"照林坊庫裏","kana":"しょうりんぼうくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80917677,"lng":132.84682395,"geo_status":"db","era":"享和元年(1801)","year":1801,"year_source":"converted","year_min":1801,"year_max":1801,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積315㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0119","desc":"本堂の後方に位置する。切妻造妻入桟瓦葺で、北・東面に下屋を付ける。桁行22ｍ梁間14ｍの大規模な庫裏で、正面寄りに土間を設け、東を大戸口、西を勝手口とする。居室部は梁行を3分して東列に畳敷を並べ、南奥に御内仏がある。近世の本格的な庫裏建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008778"},{"id":"00008782","register_sub_id":"101","register_pk":"149503","name":"照林坊山門","kana":"しょうりんぼうさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80929869,"lng":132.84779826,"geo_status":"db","era":"寛文5年(1665)／昭和中期改修","year":1665,"year_source":"converted","year_min":1665,"year_max":1665,"year_label":null,"structure":"木造、銅板葺、間口3.3m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0123","desc":"本堂の前方に位置する。間口3.3ｍの四脚門。切妻造銅板葺で、正・背面に軒唐破風を付ける。組物は支輪付の出組で、正・背面は詰組に配する。二軒繁垂木。妻虹梁大瓶束。格天井を張り、両開板戸をたてる。繰形は複雑で、絵様も繊細で手が込んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008782"},{"id":"00008775","register_sub_id":"101","register_pk":"149496","name":"照林坊本堂","kana":"しょうりんぼうほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80931048,"lng":132.8472644,"geo_status":"db","era":"嘉永5年(1852)／明治期・昭和33年改修","year":1852,"year_source":"converted","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積629㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0116","desc":"境内の中央に東面して建つ。外陣と内陣、余間からなり、正面に広縁を設け、周囲の縁先に庇柱をたて、背面に後堂を設ける大規模な真宗本堂。入母屋造本瓦葺で、正面に向拝を付設。矢来内がなく、また当初は正面縁を側面前方へまわすなど、特徴的な平面となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008775"},{"id":"00008779","register_sub_id":"101","register_pk":"149500","name":"照林坊渡り廊下","kana":"しょうりんぼうわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80923183,"lng":132.84702058,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0120","desc":"本堂と庫裏を繋ぐ東西棟の廊下。桁行21ｍ梁間2.9ｍ、両下造桟瓦葺。高く床を張り、化粧屋根裏天井、側柱筋には高欄を付ける。花頭窓を穿つ漆喰壁で南北に間仕切り、複廊とする。床下も中央筋に壁を設け、仕切る。寺格の高さを窺わせる建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008779"},{"id":"00013190","register_sub_id":"101","register_pk":"368414","name":"専教寺山門","kana":"せんきょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県安芸高田市高宮町船木字東福田1506-1","lat":34.77431389,"lng":132.75169444,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、瓦葺、間口3.9m、左右袖塀付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"34 － 0263","desc":"本堂の正面に西面して建つ。切妻造桟瓦葺の四脚門で、親柱は円柱、控柱は角柱で絵様付の虹梁を渡す。軒は二軒繁垂木、妻飾は笈形付大瓶束で破風に蕪懸魚を吊る。虹梁は菊水、木鼻は唐獅子や象、獏、大瓶束は邪鬼等多彩な彫刻で飾る。境内の表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013190"},{"id":"00013189","register_sub_id":"101","register_pk":"368413","name":"専教寺納骨堂","kana":"せんきょうじのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"広島県","address":"広島県安芸高田市高宮町船木字東福田1506-1","lat":34.77453333,"lng":132.75171667,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"34 － 0262","desc":"境内北端に南面して建つ。正面三間側面二間、宝形造桟瓦葺で、正面中央に両折桟唐戸と両脇に花頭窓を設け、彫刻欄間を嵌める。内部は畳敷の一室で、奥に仏像を安置する。柱頭は虹梁形頭貫と木鼻、台輪、尾垂木付一手先の組物で飾る。均整のとれた外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013189"},{"id":"00013188","register_sub_id":"101","register_pk":"368412","name":"専教寺本堂","kana":"せんきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市高宮町船木字東福田1506-1","lat":34.77434167,"lng":132.75198611,"geo_status":"db","era":"寛政6年（1794）／大正2年・平成6年改修","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積408㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"34 － 0261","desc":"安芸高田市北東部にある真宗本堂。外陣正面柱間七間と大規模で、内部を円柱、側廻りを角柱とし、広い畳敷の外陣、装飾的な内外陣境、内陣背後の後門等真宗本堂の典型的な平面である。向拝廻りの彫刻、外縁の格天井等随所を豪華に飾る江戸後期真宗本堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013188"},{"id":"00010350","register_sub_id":"101","register_pk":"199123","name":"南禅坊山門","kana":"なんぜんぼうさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市鞆町後地字草谷甲1339","lat":34.384163,"lng":133.379296,"geo_status":"db","era":"江戸中期／文化7年(1810)改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積5.1㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"34-0142","desc":"境内東方に開く。一間一戸四脚門の上部に方一間で入母屋造本瓦葺の上層を増築し、鐘楼を吊る。木部には全体に弁柄が塗られ、上層正背面に火灯窓、両側面に円窓を穿ち、軒先には強い反りをみせ、異国情緒を漂わせる。朝鮮通信使寄港地である鞆の浦の情景を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010350"},{"id":"00010349","register_sub_id":"101","register_pk":"199122","name":"南禅坊本堂","kana":"なんぜんぼうほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市鞆町後地字草谷甲1339","lat":34.384272,"lng":133.379041,"geo_status":"db","era":"江戸末期／昭和40年・平成7年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積315㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"34-0141","desc":"鞆町西側の寺院群内に構える境内に東面する。桁行一六メートル梁間一七メートル、入母屋造本瓦葺で一間向拝を付す。内部を内陣、余間、外陣に区分し、前面に吹放ちの広縁、三方に落縁を廻す典型的な真宗本堂平面で、要所に時代相応の発達した装飾を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010349"},{"id":"00010352","register_sub_id":"101","register_pk":"199125","name":"福泉坊庫裏","kana":"ふくせんぼうくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市吉田町吉田字下川東1334-1","lat":34.663143,"lng":132.707991,"geo_status":"db","era":"江戸末期／平成25年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"34-0144","desc":"本堂から渡廊下を介して接続して建つ。北端を土間として南側に座敷などの居室を二列並べる平面で、南列中央間は仏間とする。西列の一部では側柱を一間毎に立て、また仏壇部分は旧規は浅い押床としていた点など古様を示し、当地の真宗寺院庫裏の一例となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010352"}];
